WordHunterWoW_QuestEN[4401] = { title = "Corrupted Songflower", description = "", objectives = "" }
WordHunterWoW_QuestEN[4402] = { title = "Galgar's Cactus Apple Surprise", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, <name>. If you bring me 6 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", objectives = "Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses." }
WordHunterWoW_QuestEN[4403] = { title = "Corrupted Windblossom", description = "", objectives = "" }
WordHunterWoW_QuestEN[4421] = { title = "The Corruption of the Jadefire", description = "Not many seek adventure here... Felwood's corruption is widespread and indiscriminate.\n\nAs part of the Emerald Circle, I seek to heal this land, but there are some that wish it to fester.\n\nThe ones I speak of are the Jadefire satyrs that dwell to the northwest of here, at the Ruins of Constellas. Led by a particularly cruel satyr named Xavathras, they continue to spread the disease to any creatures they encounter.\n\nWe must defend this land that was once ours. Defeat Xavathras and destroy his minions.", objectives = "Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed." }
WordHunterWoW_QuestEN[4441] = { title = "Felbound Ancients", description = "The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves.\n\nThe satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related.\n\nWe must try to purify the flute, <name>. Bring me blessed water from the Temple of the Moon in Darnassus.", objectives = "Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial." }
WordHunterWoW_QuestEN[4442] = { title = "Purified!", description = "Using the water of Elune, I will attempt to purify the flute. We must end this suffering...\n\nMay Elune guide my hands and heart.\n\nSpeak with me again in a moment.", objectives = "Speak to Eridan again in a moment." }
WordHunterWoW_QuestEN[4443] = { title = "Corrupted Whipper Root", description = "", objectives = "" }
WordHunterWoW_QuestEN[4444] = { title = "Corrupted Whipper Root", description = "", objectives = "" }
