WordHunterWoW_QuestEN[4447] = { title = "Corrupted Night Dragon", description = "", objectives = "" }
WordHunterWoW_QuestEN[4448] = { title = "Corrupted Night Dragon", description = "", objectives = "" }
WordHunterWoW_QuestEN[4449] = { title = "Caught!", description = "Hey! Hey, you! Get over here!\n\nYa gotta help me out. I was runnin' from them Dark Iron dwarves, and I hid in here to get out of sight. Damn geologists and their magic ways! They musta seen me hide, cause next thing I knew, they locked the door and stuck me in here.\n\nTeach them geologists a lesson! Oh... an' can ya get me some pieces of silk cloth for... for... nothin'.", objectives = "Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge." }
WordHunterWoW_QuestEN[4450] = { title = "Ledger from Tanaris", description = "Oh, you know what? That reminds me.\n\nYou wanna finish up a little job I took up while I was in Tanaris? It's easy...\n\nKrinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places. Maybe you could take a look at the list and then bring it all to him?\n\nI'll just slide his ledger under the door if you're interested. Take that, and the stuff he wants back to him after ya collected it all.", objectives = "Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris." }
WordHunterWoW_QuestEN[4451] = { title = "The Key to Freedom", description = "The small brass key looks simple enough.. The only thing that seems to make it stand out are some words scratched into the head of it:\n\n\"Dark Iron Outhouse - Do Not Duplicate.\"\n\nYou have no idea what it means or what it will lead to.", objectives = "Search Searing Gorge and find a use for the Grimesilt Outhouse Key you have found." }
