WordHunterWoW_QuestEN[4485] = { title = "The Tome of Nobility", description = "Hello, <name>. I see your dedication remains strong, as does your faith.\n\nI think it is time you spoke with Duthorian Rall in Stormwind. There are some more lessons for you to learn, and I feel you are prepared.\n\nSeek him out in the Cathedral of Light, and <name>, take these lessons seriously. You've attained your status through humility and hard work, do not disappoint us by becoming arrogant.\n\nBe well.Upon completion of this quest you will gain:", objectives = "Speak to Duthorian Rall in Stormwind." }
WordHunterWoW_QuestEN[4486] = { title = "The Tome of Nobility", description = "Well, well, well, look at the mighty paladin in all <his/her> regality.\n\nSorry, <name>, I meant no offense... I just get a little jealous sometimes when I see some of the feats you've accomplished. Tiza tells me it's my weakness, and I swore to her I'd work on it. It's just hard sometimes, you know?\n\nBut the reason I wanted to talk to you was because Duthorian Rall in Stormwind sent word for you to meet him in the Cathedral of Light when you're ready. Sounded important. Sounded like something's going on.Upon completion of this quest you will gain:", objectives = "Speak to Duthorian Rall in Stormwind." }
WordHunterWoW_QuestEN[4487] = { title = "Summon Felsteed", description = "Ah, good, you're here. I sent a <succubus/infernal> after you to get your attention, but it seems you were able to get here before it found you. No matter.\n\nThere has been some talk lately of your growing power--that is good for you, possibly bad for others. But those are irrelevant points. The point is, I feel you've proven yourself and therefore are deserving of... hehe... a blessing of sorts.\n\nAbove Ratchet in the Barrens you'll find a man named Strahad. I believe you've crossed paths before.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Strahad Farsan in Ratchet." }
WordHunterWoW_QuestEN[4488] = { title = "Summon Felsteed", description = "Ah, <name>, you've seen fit to grace us with your presence. How wonderful!\n\nI hope you do not expect us to wait on you hand and foot also. You may be growing quickly in power, but you still are a pup when it comes to true knowledge and understanding. If you're not careful, corruption will overwhelm you and your weak will.\n\nBut I should get to the point: Strahad wishes to speak to you. He is still residing in his tower overlooking Ratchet in the Barrens. I suggest not taking too long.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Strahad Farsan in Ratchet." }
WordHunterWoW_QuestEN[4489] = { title = "Summon Felsteed", description = "You, <race>! Come here!\n\nYou're the one they call <name>, yes?\n\nI thought as much. I will keep this short: you're growing in power, and it has been acknowledged. And now, the time has come that you are rewarded for your efforts.\n\nGo to the Barrens. There, above Ratchet, you'll find Strahad Farsan--perhaps you remember him? He would have words with you. I wouldn't take long.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Strahad Farsan in Ratchet." }
WordHunterWoW_QuestEN[4490] = { title = "Summon Felsteed", description = "I would give you a reward for your patience and hard work. But know this, the ability to summon a Felsteed will be much more difficult in the future. You will have to earn it... and it will not be easy.\n\nFor now, go with the power to summon such a creature and use it as you see fit.You will learn:", objectives = "Speak to Strahad Farsan in Ratchet to learn the ability to summon a Felsteed." }
WordHunterWoW_QuestEN[4491] = { title = "A Little Help From My Friends", description = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Refuge. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so if I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...", objectives = "Lead Ringo to Spraggle Frock at Marshal's Refuge.\nIf Ringo faints, use Spraggle's Canteen to revive him." }
WordHunterWoW_QuestEN[4492] = { title = "Lost!", description = "You've got to help me, <name>! My friend, Ringo left earlier to explore the volcano to the south of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!", objectives = "Find Ringo at Fire Plume Ridge." }
WordHunterWoW_QuestEN[4493] = { title = "March of the Silithid", description = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.\n\nWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the silithid.", objectives = "Speak to Alchemist Pestlezugg in Gadgetzan." }
WordHunterWoW_QuestEN[4494] = { title = "March of the Silithid", description = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.\n\nWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the silithid.", objectives = "Speak to Alchemist Pestlezugg in Gadgetzan." }
WordHunterWoW_QuestEN[4495] = { title = "A Good Friend", description = "A friend of mine named Iverron usually visits me at the same time every day. The strange thing is that he hasn't been by today at all -- he's several hours late, in fact.\n\nI admit, I am a little worried, <name>. Iverron spends a lot of time over by the cave to the north, and I'm sure you know how dangerous it is there -- spiders, everywhere!\n\nIf you happen to be going that way, though, will you keep an eye out for him?", objectives = "Find Iverron by the cave to the north." }
WordHunterWoW_QuestEN[4496] = { title = "Bungle in the Jungle", description = "My research revealed to me that the silithid are like bees; destroy the queen of the hive, and the rest of should be thrown into disarray.  I'll brew a lure that we'll use to bring out the queen; once summoned, you'll take her down.\n\nFirst though, we need some reagents; we don't want you bungling into the jungle unprepared.  Go west to find the silithid hive in Un'Goro Crater and obtain a scent gland from one of the bugs.  I'll also need some samples of the native Un'Goro soil.", objectives = "Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan." }
WordHunterWoW_QuestEN[4501] = { title = "Beware of Pterrordax", description = "Wanted: A skilled fighter to deal with the threat of the Pterrordax that inhabit the Un'Goro Crater. Their numbers are growing, and they are becoming a menace to travelers in the area.\n\nDecrease the population by slaying 10 frenzied pterrordax.\n\nSpeak with Spraggle Frock after completing the task for a reward.", objectives = "Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge." }
WordHunterWoW_QuestEN[4502] = { title = "Volcanic Activity", description = "Being an apprentice to Marvon Rivetseeker, I've learned so much. But he's been gone for such a long time now, so I think I'm going to work on some experiments of my own.\n\nI've been reading about Un'Goro Crater most recently, and about the strange volcanic activity going on in the middle of the crater. I think a lot could be learned if I could just get some of the ash from the elementals there.\n\nDo you think you'd mind collecting some for me, if you are going that way?", objectives = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet." }
WordHunterWoW_QuestEN[4503] = { title = "Shizzle's Flyer", description = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax and diemetradon would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?", objectives = "Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge." }
WordHunterWoW_QuestEN[4504] = { title = "Super Sticky", description = "I'm always looking for a quick way to earn a gold, <name>. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nHead to the tar pits in northern Un'Goro Crater, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. Regular tar just simply isn't sticky enough.\n\nThe plant-like creatures contain chlorophyll in their skin, and mixed with the tar, it's super sticky!", objectives = "Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan." }
WordHunterWoW_QuestEN[4505] = { title = "Well of Corruption", description = "Some may say that I am exceptionally cruel... But truly, it is only a strong desire to see the Horde gain an advantage against the Alliance, in any way possible.\n\nMy newest interest is a moonwell at the Ruins of Constellas, south of here, tended by the Jadefire satyrs. The moonwell, once a symbol of renewal for the insufferable night elves, is now corrupted, and used to bring forth more satyrs.\n\nI have an idea, <name>, and I'd like a sample of the water... for my little feline friend here.", objectives = "Collect a sample of corrupted water from the Jadefire Satyrs' moonwell and bring it to Winna Hazzard at Bloodvenom Post." }
WordHunterWoW_QuestEN[4506] = { title = "Corrupted Sabers", description = "This corrupted water can be used to our advantage, <name>. With just a small amount of the water, my kitten doubled in size, and seems to be stronger... somehow. These cats may prove useful...\n\nHere, <name>. Take this cat carrier, and release the kitten inside next to the moonwell in the Ruins of Constellas. Heh, heh... I'm sure you'll be pleased with the results!\n\nReturn the cat to me, and I'm sure I can make it worth your time.", objectives = "Take Winna's kitten to the corrupted moonwell, release it, then bring it back to Winna.\nOnce you have returned to Winna, click on the cat to release it to Winna." }
WordHunterWoW_QuestEN[4507] = { title = "Pawn Captures Queen", description = "Here's the lure.  Inside the hive network should be a crystal of some sort.  We think the silithid use the crystal as some sort of hive-wide attunement device.  As for where this crystal might be, I'd say try the hatcheries inside the hive.\n\nUsing the lure on the crystal should roust out the queen, but be warned - she will probably be protected by several guards.  Take out the queen and remove her brain.  As icky as that sounds, we desperately need to study it.  Good luck, <name>!", objectives = "Defeat the Gorishi Hive Queen once she is summoned.\nBring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan." }
WordHunterWoW_QuestEN[4508] = { title = "Calm Before the Storm", description = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.\n\nTake my latest report back to Gracina Spiritmight in Darnassus; she's still at the Temple of the Moon, is she not?  She's got friends who are Alliance bigwigs; if we can get them involved in this <name>, then we just might make it out of this alive.", objectives = "Bring Pestlezugg's Un'Goro Report to Gracina Spiritmight in Darnassus." }
WordHunterWoW_QuestEN[4509] = { title = "Calm Before the Storm", description = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.\n\nTake my latest report back to Zilzibin Drumlore in Orgrimmar; he's still in his place on the upper part of the Drag, is he not?  He's got friends who are high within the Horde; if we can get them involved in this <name>, then we just might make it out of this alive.", objectives = "Bring Pestlezugg's Un'Goro Report to Zilzibin Drumlore in Orgrimmar." }
WordHunterWoW_QuestEN[4510] = { title = "Calm Before the Storm", description = "<name>, your help has been immeasurable.  The time will come, no doubt, when I'll ask for your assistance against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.\n\nTake this note to Idriana at the bank.  She'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, brave <class>.", objectives = "Bring the Bank Voucher to Idriana in the bank of Darnassus." }
WordHunterWoW_QuestEN[4511] = { title = "Calm Before the Storm", description = "<name>, we could not have gotten this far without you.  The time will come soon, no doubt, when I'll ask for your help against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.\n\nTake this note to Karus at the bank.  He'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, mighty <class>.", objectives = "Bring the Bank Voucher to Karus in the bank of Orgrimmar." }
WordHunterWoW_QuestEN[4512] = { title = "A Little Slime Goes a Long Way", description = "But the thing I've studied most is ooze. I know it sounds odd, but they're all over!\n\nI helped a lady in Menethil find her bag not too long ago--it was eaten by oozes. I've seen members of the Royal Apothecary Society from Undercity collecting samples of the stuff. I want to know why! Where does it come from?\n\nI've heard of more in Felwood. What I need are samples of the oozes there so I can further my research. I'll give you containers, you use them to collect a sample from the deceased creatures.", objectives = "Bring 6 Filled Cursed Ooze Jars and 6 Filled Tainted Ooze Jars to Laris Geardawdle in Ironforge." }
WordHunterWoW_QuestEN[4513] = { title = "A Little Slime Goes a Long Way", description = "I'm going to need more samples, {name}. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure. I do know that these are corrupt... just like Felwood. Which is what makes my realization so important. The oozes seem to adapt... to take on the aspects of the area they're in. I'll need to find samples that haven't been polluted. But where? Where?!\n\nBah! {name}, take these containers just in case you find any on your own.", objectives = "Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.\nIf you have trouble finding them, perhaps try to get more clues from Laris." }
WordHunterWoW_QuestEN[4521] = { title = "Wild Guardians", description = "Winterspring lies just beyond Timbermaw, northeast of Felwood. Have you been there?\n\nI have heard that the area is laden with creatures called wildkin. These beasts have been known to guard secrets; secrets of the Night elves.\n\nWe must figure out what may be hidden in Winterspring.\n\nI have heard the ragged owlbeasts can be found just south of the road, and that there are others called raging owlbeasts that may be found in the center of Winterspring. Clear them out, and gain access to the land.", objectives = "Trull Failbane in Felwood wants you to kill 15 Raging Owlbeasts and 15 Ragged Owlbeasts." }
WordHunterWoW_QuestEN[4542] = { title = "Message to Freewind Post", description = "Brave traveler, the centaurs have increased their attacks in this area. Freewind Post must know about this renewed harassment immediately! Seek Cliffwatcher Longhorn at Freewind Post to the southeast and give him this urgent message.\n\nBe warned, avoid the Grimtotem Clan nearby... they have been acting strange toward us lately.", objectives = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post." }
WordHunterWoW_QuestEN[4561] = { title = "Testing for Impurities - Un'Goro Crater", description = "", objectives = "" }
WordHunterWoW_QuestEN[4581] = { title = "Kayneth Stillwind", description = "The druid Kayneth Stillwind sent word to me.  He would like a report of the happenings along our coast and in the forests surrounding Astranaar.  He fears there is a corruption moving through Ashenvale... and he may be right.\n\nHere, take my report to him.  You will find him in the shrine of Forest Song, in the Nightsong Woods to the east.", objectives = "Take Shindrell's Note to Kayneth Stillwind in Forest Song." }
WordHunterWoW_QuestEN[4601] = { title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", objectives = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine." }
WordHunterWoW_QuestEN[4602] = { title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give the Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", objectives = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine." }
