WordHunterWoW_QuestEN[4604] = { title = "More Sparklematic Action", description = "", objectives = "" }
WordHunterWoW_QuestEN[4605] = { title = "The Sparklematic 5200!", description = "", objectives = "" }
WordHunterWoW_QuestEN[4606] = { title = "The Sparklematic 5200!", description = "", objectives = "" }
WordHunterWoW_QuestEN[4621] = { title = "Avast Ye, Admiral!", description = "Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o' plunder.  Were ye to put a knife to Fleet Master Seahorn, we'd ne'er run afoul of a Booty Bay's vessel.  Were ye to put a knife to Baron Revilgaz, we'd ne'er face the law on their terms.\n\nIf ye are to be an honorary admiral amongst us - yes, ADMIRAL, you'll puts a knife to both of 'em as I've says.  Go now lad, and return to me once ye does the deeds.", objectives = "Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale." }
WordHunterWoW_QuestEN[4641] = { title = "Your Place In The World", description = "Finally, you are of age, <name>... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.\n\nYes...\n\n<Kaltunk looks you over.>\n\nYou will do nicely.\n\nNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.\n\n<Kaltunk laughs.>\n\nReport to Gornek, he should be able to assign a task better suited to a young <class>. You will find Gornek in the Den, to the west.", objectives = "Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west." }
WordHunterWoW_QuestEN[4642] = { title = "Melding of Influences", description = "Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely. When you get close enough, release the ooze in the case, and let us see what the two think of one another.\n\nAfter the experiment concludes, bring me a sample of whatever is left over. I will await you here in the Apothecarium.", objectives = "Bring a Merged Ooze Sample to Chemist Fuely in Undercity." }
WordHunterWoW_QuestEN[4661] = { title = "Testing for Corruption - Felwood", description = "", objectives = "" }
WordHunterWoW_QuestEN[4681] = { title = "Washed Ashore", description = "That beached creature is not an isolated incident here in Darkshore.  There are more along the coastline and even in the water.  I would like for you to investigate another one that we know of; this one was reported to be in the water due west of Auberdine, close to a sunken vessel.  Return to me with anything that you may recover that would aid our research.\n\nAlso, in your travels you may find other creatures.  By all means, if you should discover anything then please bring it to our attention!", objectives = "Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine." }
WordHunterWoW_QuestEN[4701] = { title = "Put Her Down", description = "You have no doubt seen the worgs which the Blackrock orcs command.\n\nIt is curious - no matter how many we destroy, their numbers never dwindle. My scouts have reported that the worgs are bred, trained, and ultimately exported from Blackrock Spire: capital city of the Blackrock orcs. You must travel to Blackrock Spire and discover the source of this menace. Discover... and destroy.\n\nGood luck, <name>. May Cenarius protect you...", objectives = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg." }
WordHunterWoW_QuestEN[4721] = { title = "Wild Guardians", description = "Runners have returned from Winterspring with reports that there is a series of small caves in the southern area of Winterspring. It seems that there are wildkin situated in the area around these caves. If there is something valuable that they are guarding, I believe that this is the place we will find it.\n\nYou will find these to be more of a challenge than the previous types, <name>. The creatures seem to have gone mad from exposure to the very thing that they strive to protect.", objectives = "Trull Failbane in Felwood wants you to hunt 10 Berserk Owlbeasts in Winterspring." }
WordHunterWoW_QuestEN[4722] = { title = "Beached Sea Turtle", description = "You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been scavenged by the murlocs who have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.", objectives = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4723] = { title = "Beached Sea Creature", description = "The remains of a giant thresher - much larger than one you'd expect to find in Darkshore - lie beached on the coast of the Mist's Edge.  How this creature came to be here is unknown; the group of murlocs that now feast off the carcass of it seem to be much too weak, even in large numbers, to have brought down the beast. \n\nWhile some of it has been picked clean, enough of it remains to take a sample for Gwennyth Bly'Leggonde in Auberdine to study.", objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4724] = { title = "The Pack Mistress", description = "Some say the worg controlled by the Blackrock orcs are the creation of a supernatural force. Others say they are not true worg but instead a breed of demon dog, granted to the orcs by a fallen pit lord.\n\nThe truth is far less contrived but every bit as frightening. The worg of Blackrock come from Halycon and her mate. Halycon is the gigantic den mother of the worg. Her mate? Nobody has ever lived to tell the tale of that one.\n\nStrike at the heart of the worg. Destroy Halycon... and <name>, watch your back.", objectives = "Slay Halycon, pack mistress of the Bloodaxe worg." }
WordHunterWoW_QuestEN[4725] = { title = "Beached Sea Turtle", description = "More sea turtle remains lie beached along the coastline.  This particular set has an abandoned carriage attached to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Greymist murlocs now make the remains of this creature their home, feasting off the carrion.\n\nIn the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.", objectives = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4726] = { title = "Broodling Essence", description = "I have been studying the dragonkin of the Burning Steppes for weeks, and I think I've finally had a breakthrough!  I created a device--I call it the Draco Incarcinatrix 900.  It can capture the essence of dragon whelp broodlings!\n\nOr, at least I think it can.\n\nHere, take the device and zap a broodling in the Burning Steppes with it.  While it's under the device's effects, defeat the broodling and its essence should be released.\n\nIf it is, then splendid!  Bring me back samples so I can study them!", objectives = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes." }
WordHunterWoW_QuestEN[4727] = { title = "Beached Sea Turtle", description = "The skeletal remains of a sea turtle lie in the sand of the northern Darkshore beaches.  The Greymist murlocs have either not found this carcass, or perhaps they have and are shying away from it for some unknown reason.  Regardless, there is enough of the turtle left to take a sample back to Gwennyth Bly'Leggonde in Auberdine for the Temple of the Moon to study.", objectives = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4728] = { title = "Beached Sea Creature", description = "The corpse of what appears to be some sort of giant sea mammal lies partially gutted on the beach.  A wheelbarrow and various tools lie abandoned by this enormous beached sea creature, as though an attempt to study it had been made previously.  Though murlocs have scavenged this beast, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.", objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4729] = { title = "Kibler's Exotic Pets", description = "You're probably wondering what I'm doing out here. Look at the cages! Ain't it obvious?\n\nI'm an animal lover, first and foremost, but a salesman by trade. I track down exotic animals for the rich and famous and domesticate the beasts so they behave as proper pets.\n\nNow you're probably wondering, \"What can I do for you, Kibler.\" The answer is simple: Take this here beast cage and find me some worg pups. For that, I'll domesticate a worg for you!", objectives = "Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler." }
WordHunterWoW_QuestEN[4730] = { title = "Beached Sea Creature", description = "The half-devoured corpse of what might have been a giant sea mammal lies on the beach.  A band of murlocs, stronger than those found closer to Auberdine, have taken up residence around the fallen creature.  Enough of the creature remains that a suitable sample of its bones could be delivered to Gwennyth Bly'Leggonde in Auberdine.", objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4731] = { title = "Beached Sea Turtle", description = "Another set of sea turtle remains lie beached on the coastline.  This set of remains has an abandoned carriage half buckled to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Powerful Greymist murlocs have made the carcass of this creature their current home.\n\nIn the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.", objectives = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4732] = { title = "Beached Sea Turtle", description = "You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been picked nearly clean by Greymist murlocs, the very ones who now have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.", objectives = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4733] = { title = "Beached Sea Creature", description = "The remains of what appear to be a giant thresher have washed ashore on the rocky inlet of the Twilight Shore.  The thresher is several times larger than any of the other threshers spotted in these parts.  Wherever it came from, this creature would not seem to have been native to Darkshore.\n\nThough the creature has been picked apart in places, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.", objectives = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine." }
WordHunterWoW_QuestEN[4734] = { title = "Egg Freezing", description = "<name>, I've been working hard on a new device, the eggscilloscope!  It's designed to project a burst of cold energy at the egg of a black dragon... and freeze it solid!  Can you test it for me?\n\nI heard that high up in Blackrock Spire, the dragons have a rookery where they hatch their eggs.  That's where you'll have to go to test the eggscilloscope, and then let me know how it worked!\n\nAnd don't worry.  Frozen dragon eggs should be harmless.  It's the unfrozen ones you have to worry about!", objectives = "Use the Eggscilloscope Prototype on an egg in the Rookery." }
WordHunterWoW_QuestEN[4735] = { title = "Egg Collection", description = "<name>, I'm finally ready for real samples of dragon eggs!  Here, take this collectronic module.  It's designed to extract a dragon egg and prepare it for transport.  Go back to the Rookery and use the module to collect eggs.\n\nAnd don't forget to freeze them first, or they might hatch before you can collect them!\n\nWhen you have enough eggs, bring them to me!", objectives = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes." }
WordHunterWoW_QuestEN[4736] = { title = "In Search of Menara Voidrender", description = "Ah, hello, <name>. You're progressing well in your training. So well in fact that I think you should be rewarded for your hard work--and for not becoming corrupted by the arcane yet.\n\nIf you're interested, seek out Menara Voidrender in Ratchet. She is currently staying at Strahad Farsan's tower overlooking the town.\n\nShe's not very friendly, <name>, so don't expect any praise. But if you work hard, she'll make sure you're taken care of.Upon completion of this quest you will gain:", objectives = "Speak to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4737] = { title = "In Search of Menara Voidrender", description = "Hmph, still you strive to become more powerful. I say it's only time before the corruption and addiction takes hold of you and you become a slave to that which you seek to gain power over.\n\nPfah! A fool you are! Time will prove me right--nothing else... just time.\n\nBut it seems that not all agree with Zevrost. It seems Menara would create tools for you to become more powerful and to harness your strength. If you're interested, then go to Ratchet in the Barrens. She is there overlooking the town.Upon completion of this quest you will gain:", objectives = "Speak to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4738] = { title = "In Search of Menara Voidrender", description = "Let us be clear about one thing, <name>: I don't feel you are ready for such responsibilities. I don't think aiding in the creation of any item of power is something a novice should ever be involved in; especially one so untested.\n\nBut that's not my decision. The powers that be, or at least the ones that do wish to impart such gifts upon you get to decide that.\n\nIf you're interested in learning more, I suggest you seek out Menara Voidrender in Ratchet. She usually resides in the tower above the port town.Upon completion of this quest you will gain:", objectives = "Speak with Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4739] = { title = "In Search of Menara Voidrender", description = "<class>! Yes, you!\n\nYou don't have all the accoutrements, but it's plain to see you're ready--the air around you exudes greater confidence. Yes, I see it now.\n\nMenara Voidrender would teach you a few things if you feel you're ready. She spends her time tutoring younger students in the arcane. She even gives gifts to those who pass her tests.\n\nGo to Ratchet in the Barrens if you're interested. She's above the city in Strahad's tower.Upon completion of this quest you will gain:", objectives = "Speak to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4740] = { title = "WANTED: Murkdeep!", description = "Attention!\n\nA reward is being offered for the death of the murloc \"Murkdeep\".  This foul beast is known to be responsible for the death of at least one Sentinel, and is suspected of causing the sinking of at least two cargo vessels in the waters off Darkshore!\n\nMurkdeep was last spotted at a hutted murloc camp south of Auberdine, and is thought to be protecting the huts there.  Reward claims for this bounty should be claimed with Sentinel Glynda Nal'Shea in Auberdine.\n\nThe Auberdine Village Council", objectives = "Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.\nReport the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine." }
WordHunterWoW_QuestEN[4741] = { title = "Wild Guardians", description = "In the northern areas of Winterspring, the Wildkin grow even more ferocious. We must continue our measures there.\n\nHunt the moontouched owlbeasts in Winterspring, and explore the area they inhabit.\n\nThis is dangerous ground, but I know that you will be able to handle the challenge. Return to me after you have slain 13 of the wildkin.", objectives = "Trull Failbane in Felwood wants you to hunt 13 Moontouched Owlbeasts." }
WordHunterWoW_QuestEN[4742] = { title = "Seal of Ascension", description = "As you can see, the unadorned seal has three empty sockets. Each of those sockets must be filled with a gemstone representing the leadership's command. Finally, Overlord Wyrmthalak, master of the lower citadel, must forge the seal in the flames of the Black Dragonflight.\n\nUnderstand this, mortal: the chance that one of the three generals of the lower citadel would carry a gemstone at any given time is rare. You must be vigilant in your quest. Remain determined!", objectives = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe." }
WordHunterWoW_QuestEN[4743] = { title = "Seal of Ascension", description = "Few of the black dragonkin, outside of those in the upper citadel, have the ability to forge the seal with their own flaming breath. Wyrmthalak is one such dragonkin, but his will is unbreakable.\n\nYou must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find an ancient drake known as Emberstrife. You must break his will, <name>. Break it and use this orb on his weakened form. You will have scant seconds to control his mind and fan the flames that will forge the seal.", objectives = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!" }
WordHunterWoW_QuestEN[4761] = { title = "Thundris Windweaver", description = "Your scouting of the furbolg camp is information that Thundris Windweaver should be made aware of.  He graciously serves as the elder of Auberdine, offering sage and just stewardship of the day to day affairs of the village.  Please - share with him your findings to date on the furbolg situation.\n\nI believe he has some ideas of his own on the reasons behind their corruption.  Perhaps you can work with him to enact a plan to restore the balance of nature here!", objectives = "Speak with Thundris Windweaver in Auberdine." }
WordHunterWoW_QuestEN[4762] = { title = "The Cliffspring River", description = "The Cliffspring River has begun turning foul and corrupted.  It empties into the Mist's Edge, and I fear the wash will affect Auberdine soon.  I suspect the Blackwood furbolgs up-river are the cause of the taint, but I also suspect that they aren't the true root of it.\n\nTake this sampling tube and go to the mouth of the river to our north.  Proceed inland to the first waterfall and draw a sample from the pool there.  You'll see a bridge overhead.  Once you have a sample, return to me in Auberdine.", objectives = "Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.\nReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample." }
WordHunterWoW_QuestEN[4763] = { title = "The Blackwood Corrupted", description = "We've learned that a source of furbolg corruption is from the satyr.  They hold sway via talismans that they channel magic through.  If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!\n\nFill this bowl at our moonwell and take samples of the furbolgs' food from their northern camp.  Mix them and place it near the bonfire by the river; any furbolgs who eat will be cleansed just long enough to lure out the satyr corruptor... who then you must slay!", objectives = "Fill the Empty Cleansing Bowl at the Auberdine Moonwell.\nGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.\nMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.\nTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine." }
WordHunterWoW_QuestEN[4764] = { title = "Doomrigger's Clasp", description = "There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune.  It was where the Dark Iron dwarves kept their relics, trophies and objects of art.\n\nThat was long ago.  It is said the hall has collapsed and is now used for... less savory tasks.  But I believe some old dwarven relics may still be found there.\n\nOne such relic is Doomrigger's clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it.\n\nThat clasp, <name>, is your goal.", objectives = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes." }
WordHunterWoW_QuestEN[4765] = { title = "Delivery to Ridgewell", description = "I have packaged Doomriggers Clasp into a crate, suitable for shipment to Stormwind.  <name>, you have been extremely helpful -- can I ask you for one last favor?\n\nDeliver the crate to Count Remington Ridgewell.  You will find him in the Keep of Stormwind.  I am sure he'll be very pleased to see what you have for him.", objectives = "Bring Ridgewell's Crate to Remington Ridgewell in Stormwind." }
WordHunterWoW_QuestEN[4766] = { title = "Mayara Brightwing", description = "An agent of mine, Mayara Brightwing, was sent to the Burning Steppes to scout the ruined city of Thaurissan.  That destroyed city of the Dark Iron dwarves may hide objects of great value... objects that would fit nicely into our family museum.\n\nMayara says she found something and will need aid in retrieving it, but it is not in Thaurissan.  Instead, a foray into Blackrock Spire will be required.\n\nI do not know the details, but if interested then speak with Mayara in the Burning Steppes.", objectives = "Speak with Mayara Brightwing in the Burning Steppes." }
WordHunterWoW_QuestEN[4767] = { title = "Wind Rider", description = "I've been tasked to recruit more wyverns for the master wind riders. Their numbers are growing and I myself hope to become a wind rider one day. However, we cannot train enough wyverns to keep up with the demand. Perhaps you can help me, <name>.\n\nI need you to travel to Highperch to gather some wyvern eggs. From here, head northwest along the canyon walls to a ramp that will lead you into Highperch. Be careful, wyverns are very protective over their eggs and they will not be kind to intruders.", objectives = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post." }
WordHunterWoW_QuestEN[4768] = { title = "The Darkstone Tablet", description = "The Darkstone Tablet holds the writings of the long-dead dwarf Urheld Darkstone.  An alchemist of great skill, he was thought insane by his contemporaries and, hence, did not share his research.\n\nBut he did etch it onto tablets, and I believe one such tablet lies in Blackrock Spire, in a chamber once named the Hall of Fortune.  I know not what it is now called, for few enter Blackrock and return.\n\nBut if you are willing to brave its dangers and return to me with the tablet, your reward will be great.", objectives = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath." }
WordHunterWoW_QuestEN[4769] = { title = "Vivian Lagrave and the Darkstone Tablet", description = "Vivian Lagrave sent me word from Kargath, in the Badlands.  Through her studies, she believes there is an ancient text within Blackrock Spire that would benefit our research.  To confirm this, she will need someone to extract the text from the spire.  No easy task.\n\nIf interested, then speak with Vivian in Kargath.", objectives = "Speak with Shadowmage Vivian Lagrave." }
WordHunterWoW_QuestEN[4770] = { title = "Homeward Bound", description = "Please help me, <class>! I've been hiding here in Highperch for some time now and it's been days since I've seen a friendly face. I came here to study the wyvern and I think I got a little too close. After being chased away from one of the nests I got lost.\n\nI need to get back to Whitereach Post! Motega does not know that I am missing and will be furious to know that I ventured into Highperch by myself.\n\nWhitereach Post is just east of here... please take me there!", objectives = "Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post." }
WordHunterWoW_QuestEN[4771] = { title = "Dawn's Gambit", description = "I've placed Dawn's Gambit in the container you brought to us, the one that held the dragon eggs.  Your job is to bring it deep within the Scholomance.\n\nThe undead mage Vectus leads a team of Scourge scholars... place Dawn's Gambit in their chamber, called the \"viewing room.\"  It will then react with the undead found there and, with a little luck, destroy them!\n\nAfter that, defeating Vectus shouldn't be a problem.  Right?", objectives = "Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink." }
WordHunterWoW_QuestEN[4781] = { title = "Components for the Enchanted Gold Bloodrobe", description = "Your next task is as simple as your first, but will require you to seek out aid.\n\nI require gold thread for the embroidery of the cloak, but gold thread is not easy to come by, and very few know how to make it. Fortunately, one who is loyal to our cause knows its secrets and is willing to help those rising in our ranks.\n\nBring a gold bar to Xizk Goodstitch in Booty Bay. He is a master tailor and will be happy to spin the thread for you. Gold bars are smelted by skilled miners. Ask a miner for help.Upon completion of this quest you will gain:", objectives = "Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale." }
WordHunterWoW_QuestEN[4782] = { title = "Components for the Enchanted Gold Bloodrobe", description = "Return to Menara, tell her it'll take some time, but I'll make sure to come through for her... and you. Tell her to have you finish gathering the rest of your components--I should have the thread done by then. You can return and pick it up then.\n\nGood luck, <name>. Oh, and say hello to Strahad for me while you're there. That old coot... putting a tower right there next to Ratchet... crazy.Upon completion of this quest you will gain:", objectives = "Return to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4783] = { title = "Components for the Enchanted Gold Bloodrobe", description = "The next components are found in Desolace, far to the west of the Barrens and even the Stonetalon Mountains.\n\nThere, chaos still reigns after the Sundering. Both your strength and cunning will be tested there--you will face creatures of hatred and also of the Burning Legion.\n\nFrom the Hatefury satyr in the northeast, bring me their blood. From the lesser infernals in Mannoroc Coven, bring me a lesser infernal stone.\n\nWe will use both in the construction of your robe.Upon completion of this quest you will gain:", objectives = "Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4784] = { title = "Components for the Enchanted Gold Bloodrobe", description = "I need only three things now, <name>, then we can finish your robe.\n\nFirst, the fine gold thread Xizk is making for you. Return to him in Booty Bay and get it.\n\nSecond, bring me two smoldering coals from the fire elementals in the Arathi Highlands. If I recall correctly, they are to the west, near Thoradin's Wall.\n\nFinally, a soul shard created by you.\n\nAfter you have all the components, return here to the tower and I will complete the robe for you.Upon completion of this quest you will gain:", objectives = "Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4785] = { title = "Fine Gold Thread", description = "", objectives = "" }
WordHunterWoW_QuestEN[4786] = { title = "The Completed Robe", description = "I will put the robe together for you now. It will take but a few moments. Do not go far.You will receive:", objectives = "Wait for Menara Voidrender to complete your robe and then speak to her again." }
WordHunterWoW_QuestEN[4787] = { title = "The Ancient Egg", description = "The Prophecy of Mosh'aru speaks of an ancient egg.  It is a relic of a time when trolls ruled vast empires, and it has the power to hold the essence of Hakkar.  It may be the only way to keep our world safe from his evil.\n\nBring me the ancient egg, <name>.  It is said to lay hidden deep within Jintha'Alor in the Hinterlands, in a cave behind the amphitheater at the top of the city.", objectives = "Bring the Ancient Egg to Yeh'kinya in Tanaris." }
WordHunterWoW_QuestEN[4788] = { title = "The Final Tablets", description = "While I look over the third and fourth tablets of Mosh'aru, you must find the fifth and sixth!  It will not be easy, for they are held by the Smolderthorn trolls within Blackrock Spire.  The spire is a dark mountain of fire between the Burning Steppes and the Searing Gorge.\n\nGood luck, <name>.  Blackrock Spire is no place for decent folk...", objectives = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris." }
WordHunterWoW_QuestEN[4801] = { title = "Frostsaber E'ko", description = "", objectives = "" }
WordHunterWoW_QuestEN[4802] = { title = "Winterfall E'ko", description = "", objectives = "" }
WordHunterWoW_QuestEN[4803] = { title = "Shardtooth E'ko", description = "", objectives = "" }
WordHunterWoW_QuestEN[4804] = { title = "Chillwind E'ko", description = "", objectives = "" }
WordHunterWoW_QuestEN[4805] = { title = "Ice Thistle E'ko", description = "", objectives = "" }
WordHunterWoW_QuestEN[4806] = { title = "Frostmaul E'ko", description = "", objectives = "" }
WordHunterWoW_QuestEN[4807] = { title = "Wildkin E'ko", description = "", objectives = "" }
WordHunterWoW_QuestEN[4808] = { title = "Felnok Steelspring", description = "I have another favor to ask of you.\n\nMy initial study of the essence you collected shows that it might be possible to freeze dragon whelp eggs and preserve them!  I want to test this theory, but first I need specially made engineering components.  My colleague, Felnok Steelspring, can make them.\n\nHere, take this letter to Felnok.  It tells him what I need.  You'll find Felnok in Winterspring, in the town of Everlook.", objectives = "Give Tinkee's Letter to Felnok Steelspring." }
WordHunterWoW_QuestEN[4809] = { title = "Chillwind Horns", description = "I have most of what Tinkee needs, but I'm missing one important component, and that's chillwind horns.  The horns of the chillwind chimaera in Winterspring are a concentrated source of cold, but only pristine, uncracked horns will do!  I'll need a supply of those to complete Tinkee's order.\n\nBring me the uncracked chillwind horns, and I'll prepare a package for Tinkee.", objectives = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring." }
WordHunterWoW_QuestEN[4810] = { title = "Return to Tinkee", description = "Ok, everything is prepared and packed and ready for transport!  Good luck in your journey, and make sure you tell Tinkee that she owes me!", objectives = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes." }
WordHunterWoW_QuestEN[4811] = { title = "The Red Crystal", description = "Hostile moonkin roam in ever increasing numbers to our east.  They once were thought to be gentle, almost mystical creatures.  While some continue to hold reverence for them, the safety of Auberdine forces me to keep a more realistic view.\n\nI've received reports that moonkin are being drawn to a large red crystal along Darkshore's eastern mountain range.  No one has any idea what that crystal is, or even if it really exists.  I want you to locate it over there and report back to me what you find.", objectives = "Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range. Report back what you find to Sentinel Glynda Nal'Shea in Auberdine." }
WordHunterWoW_QuestEN[4812] = { title = "As Water Cascades", description = "Use this empty vial and fill up on some moonwell water here in Auberdine.  Such potent magic should provide a clue as to the composition of the crystal.  To do that, you'll pour the liquid over the crystal; it should take care of the rest.\n\nWhile I don't anticipate anything bad happening to you, I still want you to be careful.  Above us to the east is Felwood; if that crystal is tied to that place as I suspect it is, then it could prove to be very dangerous.", objectives = "Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall." }
WordHunterWoW_QuestEN[4813] = { title = "The Fragments Within", description = "The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone.  The jawbone appears to be from a humanoid, but it is unclear without breaking open the crystal - a feat that even the strongest of magic would find near impossible.\n\nWith the task at hand complete, all that remains is to report back to Sentinel Glynda Nal'Shea in Auberdine.", objectives = "Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine." }
WordHunterWoW_QuestEN[4821] = { title = "Alien Egg", description = "A rumor has surfaced about an alien egg here in Thousand Needles. Those that report seeing this egg have failed to even get close enough to examine it in detail. Serpents guard the egg as if it's one of their own.\n\nI want you to seek out this alien egg and bring it to me so that I may examine it. Reports say the egg is located within a serpent den, but there are several serpent dens along the base of the cliff walls south and northeast of Freewind Post.", objectives = "Return the Alien Egg to Hagar Lightninghoof in Freewind Post." }
WordHunterWoW_QuestEN[4822] = { title = "You Scream, I Scream...", description = "ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!\n\nI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule's Strawberry Ice Cream on top??!?!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Get some Strawberry Ice Cream for your ward. The lad seems to prefer Tigule and Foror's brand ice cream." }
WordHunterWoW_QuestEN[4841] = { title = "Pacify the Centaur", description = "<name>, I entreat you to hunt these centaur down. They shall feel the wrath of our revenge. Attack the centaur camp to the north of Freewind Post!  Let wrath guide your hand!", objectives = "Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post." }
WordHunterWoW_QuestEN[4842] = { title = "Strange Sources", description = "To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs...\n\nWell, I think you'll want to see it for yourself. You'll need to travel the length of Winterspring, and head to the very south. When the air becomes thick and muggy, and the sky turns dark, you'll have found what I believe to be the source of the hot springs.\n\nHave a look. I'm sure you'll have many questions when you return.", objectives = "Follow Donova Snowden's instructions, then report back." }
WordHunterWoW_QuestEN[4861] = { title = "Enraged Wildkin", description = "Hey there, <lad/lass>! I was chased from my camp in southern Winterspring by some bloodthirsty wildkin! Well, I suppose I got too close to something the wildkin were guarding.\n\nI barely managed to get away safely; I fear a buddy of mine wasn't as lucky. Would you mind braving the wildkin and heading to the camp? I really need my supplies, and I'd also like to get back the amulet I unearthed yesterday at the dig site.", objectives = "Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring." }
WordHunterWoW_QuestEN[4862] = { title = "En-Ay-Es-Tee-Why", description = "Believe it or not, there are people out there willing to pay for the most vile of domesticated beast!\n\nI'd sent Bijou into the Spire to try and collect some of those spire spider eggs but I haven't heard from her in weeks. Maybe you can help me out?\n\nI'll tell you what, <name>. Go to Blackrock Spire and collect some spire spider eggs for me. Bring them back here and not only will I give you a little cash, but I'll even domesticate one for you!", objectives = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\nBy the sound of it, these eggs could be found near spiders." }
WordHunterWoW_QuestEN[4863] = { title = "Enraged Wildkin", description = "Looking around, you don't see much that Jaron could want here. However, you do notice that the crate you found has been smashed open, almost as if this was what the wildkin were after...\n\nLooking to the east, you can barely make out an abandoned wagon. Perhaps you might find Jaron's things there. It's worth a look.", objectives = "Find Jaron Stoneshaper's wrecked wagon." }
WordHunterWoW_QuestEN[4864] = { title = "Enraged Wildkin", description = "After inspecting the contents of the box, you decide that Jaron could make use of the tools and other items inside. However, there is no sign of the amulet.\n\nIt appears that the wildkin inhabit the lands to the north and east of here, so you decide that the next step is to face the creatures and reclaim the amulet from them.", objectives = "Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of.\nBring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring." }
WordHunterWoW_QuestEN[4865] = { title = "Serpent Wild", description = "If I did not see that with my own eyes I would never have believed it to be true. Vengeance has come to Thousand Needles!\n\n<Hagar wipes his brow.>\n\n<name>, you must act quickly! Go now and seek out Motega Firemane; he is located at Whitereach Post just northwest of Freewind Post along the road. He will know what to do!", objectives = "Report your findings to Motega Firemane." }
WordHunterWoW_QuestEN[4866] = { title = "Mother's Milk", description = "It's probably one of the most potent poisons in the world, <race>!\n\nI've overheard the Blackrock speaking about its lethality in my jaunts into the Spire. They call it 'Mother's Milk', named after Mother Smolderweb, the big nasty spider in the Skitterweb cave.\n\nNow here's what I need from you: A live sample of the Milk, flowing through YOUR veins. Just bringing me the gland won't be enough! Get her to poison you and come back to me!\n\nThen... I get to milk ya!\n\n<Rubs his hands together in anticipation.>", objectives = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you." }
WordHunterWoW_QuestEN[4867] = { title = "Urok Doomhowl", description = "Argh!  So hard to speak!\n\nTake this note!  Get me my mojo!", objectives = "Read Warosh's Scroll. Bring Warosh's Mojo to Warosh." }
WordHunterWoW_QuestEN[4881] = { title = "Assassination Plot", description = "The Tauren, Kanati Greycloud is bold to set up a hunting camp in Thousand Needles. We must kill him to rid this hunting camp and all who may follow him. We will converge at the small post Southwest of the Great Lift.", objectives = "Warn Kanati Greycloud at Whitereach Post of the plot to kill him." }
WordHunterWoW_QuestEN[4882] = { title = "Guarding Secrets", description = "You are unsure of the significance of the necklace that fell from the neck of the recently-slain wildkin. It glows brightly, slowly fading in and out.\n\nTrull Failbane might be able to tell you more, since his knowledge of the wildkin seems extensive. Perhaps you should ask him about it.", objectives = "Take the Blue-feathered Necklace to Trull Failbane at Bloodvenom Post." }
WordHunterWoW_QuestEN[4883] = { title = "Guarding Secrets", description = "While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield. But I do believe I know of one that would be able to examine the necklace and most likely tell you what it is.\n\nNara Wildmane in Thunder Bluff is an expert in this field; see her. Good luck, <name>.", objectives = "Take the Blue-feathered Necklace to Nara Wildmane." }
WordHunterWoW_QuestEN[4901] = { title = "Guardians of the Altar", description = "At the very top of the ridge lies what I believe to be an altar of the goddess Elune. From what I can tell, we need to light the five torches in each cave, and then we will be able to access the altar directly.\n\nI transcribed some incantations carved into the stone in the ancient ruins of Kel'Theril, which I believe are the secret to unlocking the altar. I'll need your help to light each torch, while I recite the spell.\n\nIf we are successful, you'll be able to report our findings to Erelas!", objectives = "Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village." }
WordHunterWoW_QuestEN[4902] = { title = "Wildkin of Elune", description = "That's fascinating!\n\nI have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle. Explain to him what happened, just the same as you told me. I'm sure he will be just as interested!\n\nThis is important information, <name>!", objectives = "Speak with Arch Druid Fandral Staghelm in Darnassus." }
WordHunterWoW_QuestEN[4903] = { title = "Warlord's Command", description = "By order of Warlord Goretooth, the following inhabitants of Blackrock Spire must be destroyed:\n\nThe rotund menace, Highlord Omokk.\n\nThe cruel and ruthless troll, War Master Voone.\n\nOverlord Wyrmthalak, taskmaster of the lesser city.\n\nYou will also be required to return any important documents that you may find.\n\nSucceed and be honored.\n\nFail and be forgotten.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished." }
WordHunterWoW_QuestEN[4904] = { title = "Free at Last", description = "Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong. He... he slew my brother and then brought me here.  My poor brother...\n\n<name>, could you escort me out of the Darkcloud Pinnacle?  Please... I need to get back to Thalia! She must be worried sick about me.", objectives = "Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post." }
WordHunterWoW_QuestEN[4906] = { title = "Further Corruption", description = "A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood.\n\nXavathras and his minions were only part of a larger plan -- to cultivate a corrupted moonwell, and then provide the spoils to Xavaric.\n\nNow that Xavathras is out of the way, finish this task, <name>. Head to the north and defeat Xavaric.", objectives = "Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed." }
WordHunterWoW_QuestEN[4907] = { title = "Tinkee Steamboil", description = "Hi, <name>.  Remember Tinkee Steamboil?  Well, she remembers you!  She sent me a message to keep an eye out for you, because... she needs your help again.  I think it has something to do with her studies on dragons.\n\nYou should speak to her in the Burning Steppes, at the Flame Crest.", objectives = "Speak with Tinkee Steamboil." }
WordHunterWoW_QuestEN[4921] = { title = "Lost in Battle", description = "We battled in a small tauren camp when we were separated--she held three of the Bristlebacks off by herself. But the odds began to overwhelm us. I led some away only to see her overwhelmed by newcomers. In my rage, I turned to face my enemies, but they brought me down easily with their vast numbers.\n\nI awoke to a tauren druid tending my wounds--he had come across me on the Gold Road as I fell.\n\nPlease, <class>, find some sign of my wife.", objectives = "Find Mankrik's wife and then return to him in the Crossroads." }
WordHunterWoW_QuestEN[4941] = { title = "Eitrigg's Wisdom", description = "Rend lives?\n\nImpossible!\n\nIt had been thought that Rend  was slain decades ago.\n\nSeek out the wisdom of Eitrigg, <name>. None know the workings of the Blackrock better than he and if what is written here bares truth, Eitrigg should be informed. No person should be denied the right of vengeance.\n\nYou will find him in Orgrimmar.\n\nOnce you have spoken with Eitrigg, confer with the Warchief to find out what he wishes to do about this problem.Upon completion of this quest you will gain:", objectives = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.\nYou recall having seen Eitrigg in Thrall's chamber." }
WordHunterWoW_QuestEN[4961] = { title = "Cleansing of the Orb of Orahil", description = "Ah, a summoner's orb--this is where the taint must be coming from. We must exorcise the demon within it if you're to use it. That I can do easily.\n\nYou're the one who has the hard job.  You must kill the demon once I release it.\n\nAnd you'll have to be quick.  If you take too long then he'll return to the orb and we'll have to start over!\n\nSo get yourself ready, <name>.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.You will receive:", objectives = "Kill the Demon of the Orb, then speak with Tabetha." }
WordHunterWoW_QuestEN[4962] = { title = "Shard of a Felhound", description = "So, you have chosen to capture the soul of a felhound, good.\n\nTake this ruby--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.\n\nI would suggest going to Desolace and trying your hand at any of the felhounds there. Those should do nicely.\n\nAfter you're successful, take both the captured spirit and your ruby to Menara.Upon completion of this quest you will gain:", objectives = "Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4963] = { title = "Shard of an Infernal", description = "So, you have chosen to capture the soul of an infernal, good.\n\nTake this emerald--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.\n\nI would suggest going to Desolace and trying your hand at any of the infernals there. Those should do nicely.\n\nAfter you're successful, take both the captured spirit and your emerald to Menara.Upon completion of this quest you will gain:", objectives = "Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4964] = { title = "The Completed Orb of Dar'Orahil", description = "I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.Upon completion of this quest you will gain:", objectives = "Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again." }
WordHunterWoW_QuestEN[4965] = { title = "Knowledge of the Orb of Orahil", description = "Well, well, well... a pleasure to see you're growing in power, <name>. I'd wager you'd be about ready to speak to Menara Voidrender in the Barrens. If you haven't spoken to her before, then let me tell you, I don't think I've ever met another expert in the creation of items--orbs specifically--that can inprison even a demon to serve our will so easily.\n\nIf you're interested, she's in Strahad's tower above Ratchet in the Barrens.Upon completion of this quest you will gain:", objectives = "Speak to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4966] = { title = "Protect Kanati Greycloud", description = "But, there may be more centaur than I thought, I ask you, <name>, to fight with me against these vile assassins.", objectives = "Protect Kanati Greycloud from the centaur attack." }
WordHunterWoW_QuestEN[4967] = { title = "Knowledge of the Orb of Orahil", description = "Still a fool, and still seeking the trappings of mortals. Yes, I speak to you with arrogance. I see you before me and I laugh. You're pathetic!\n\nBut it matters not what I think. It only matters what those willing to deal with you thinks!  And in this case, against my better judgment, those with some portion of power feel you deserve more.\n\nIf this is something you strive for then you should speak with Menara Voidrender in the tower above Ratchet. I believe you have met her before some time ago.Upon completion of this quest you will gain:", objectives = "Speak to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4968] = { title = "Knowledge of the Orb of Orahil", description = "Hmm, you've made it this far... truly astonishing. I would have thought the corruption of channeling the arcane would have seeped into your very soul and driven you mad by now. How about we try and push you further then?\n\nIf you want to test your skill, seek out Menara Voidrender above Ratchet in Strahad's tower. She will guide you.Upon completion of this quest you will gain:", objectives = "Speak to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4969] = { title = "Knowledge of the Orb of Orahil", description = "Haha! You're doing very well for yourself, young <class>.\n\nGiven time, infernals and dreadlords will bow before you!\n\nBut until that time comes, you must still rely on weapons forged by the hands of the mortal races.\n\nYou seem prepared for another such creation, and if you are willing, Menara Voidrender would speak with you! She is near Strahad's tower overlooking the port town of Ratchet. Go there when you are ready.Upon completion of this quest you will gain:", objectives = "Speak to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4970] = { title = "Frostsaber Provisions", description = "If you wish to prove yourself, you may begin by doing a very simple, but very important task.\n\nGather meat from the chimaera and from the shardtooth bears in the area. Bring it to me so that I may use it to feed the frostsabers that are being trained.", objectives = "Collect 5 Shardtooth Meats and 5 Chillwind Meats for Rivern Frostwind in Winterspring." }
WordHunterWoW_QuestEN[4971] = { title = "A Matter of Time", description = "Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal!  I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted.\n\nTemporal parasites - carrion that feed on the strands of time's altered flow - now infest the silos of Andorhal.  A blue pulse of distortion is their only visual marker.  They slow my auguries; please <name>, help me by using this temporal displacer to root out these parasites.", objectives = "Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.\nSlay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands." }
WordHunterWoW_QuestEN[4972] = { title = "Counting Out Time", description = "I need you to reach into the world beyond this room, <name>.  Allow me to explain.\n\nYou see the difference in this room compared to the rest of Andorhal.  My dragonflight works in many different ways and in many different timelines.  To mend Andorhal's damage, I now act from a different timeline as not to overly contaminate it.  To continue this though I need time trinkets, ones trapped from when the plague hit.  Find them in lockboxes found in the ruined buildings that make up this once proud city.", objectives = "Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city. Return with them to Chromie in the Andorhal Inn, Western Plaguelands." }
WordHunterWoW_QuestEN[4973] = { title = "Counting Out Time", description = "If you are willing to help once more, I can certainly use your assistance.  I'll gladly take more watches you might uncover from the ruins of Andorhal.  They certainly help me in maintaining a balance against whatever malign force is meddling with the timeline here.\n\nIn exchange for those watches, I'll give you another item that, in the future, I suspect you'll find quite the use for.", objectives = "Locate 5 Andorhal Watches amongst the rubble of the city, and return with them to Chromie in the Andorhal Inn, Western Plaguelands." }
WordHunterWoW_QuestEN[4974] = { title = "For The Horde!", description = "Rend dares make such grand claims because of the protection he is afforded by the black flight.\n\nYou, <name>, will find a way to pass through the Halls of Ascension. You will then find 'Warchief' Rend Blackhand and you will destroy him - FOR THE HORDE!\n\n<Thrall slams a fist down upon his throne.>\n\nThe next time you return to my chambers, you will hold his head high in triumph and then you shall present it to your Warchief. Do this and be honored as a hero of the Horde.You will be able to choose one of these rewards:", objectives = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar." }
WordHunterWoW_QuestEN[4975] = { title = "The Completed Orb of Noh'Orahil", description = "I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice.Upon completion of this quest you will gain:", objectives = "Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again." }
WordHunterWoW_QuestEN[4976] = { title = "Returning the Cleansed Orb", description = "Take the cleansed orb back to Menara in Ratchet, <name>. Give her my regards and be safe. I truly hope you are able to withstand the temptation and corruption that is sure to come as you follow your path.\n\nGood luck.Upon completion of this quest you will gain:", objectives = "Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens." }
WordHunterWoW_QuestEN[4981] = { title = "Operative Bijou", description = "Never trust a goblin. That's what it comes down to, <name>.\n\nBijou is her name - one of our slipperiest operatives. I found out she was working for some shady exotic pet dealer out of the Burning Steppes named Kibler, in essence, two timing us. Worse yet, she was using Horde funds to finance her operations.\n\nI want her brought back here alive.\n\nShe was last seen entering Blackrock Spire. Find her and bring her back.\n\nAnd <name>, do not let her sweet talk you.", objectives = "Travel to Blackrock Spire and find out what happened to Bijou." }
WordHunterWoW_QuestEN[4982] = { title = "Bijou's Belongings", description = "At night when this place is lightly guarded, I sneak around the city, taking notes and writing down anything I see that could be of some strategic value to the K.E.F.\n\nLast night, however, things went dreadfully wrong. I stumbled across a tripwire and set off an alarm. I stashed my recon gear and ran for cover! Unfortunately, I can't get back to that gear. They've doubled and tripled up the patrols! All that information is lost.\n\nGet my belongings back and I'll return to the K.E.F. peacefully.", objectives = "Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city." }
WordHunterWoW_QuestEN[4983] = { title = "Bijou's Reconnaissance Report", description = "Take this report back to Lexlort. It will redeem my good name and will surely give the K.E.F. a strategic advantage in dealing with these orcs.\n\nCome with you? I've got way too much work to do. Get going, they need these reports as soon as possible!", objectives = "Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath." }
WordHunterWoW_QuestEN[4984] = { title = "The Wildlife Suffers Too", description = "While there was little I could do alone to thwart the Scourge, I nevertheless came to these lands to try and heal the damage done to nature.  Animals suffer from the plague that continues to choke these lands, unable to find mercy and peace.  I ask for you to continue what I could not finish here.\n\nThere is no salvation for the suffering animals but a sweet and merciful release.  Seek out diseased wolves nearby and put them down.  Please <name>, end their misery - doing so will surely soothe mine.", objectives = "Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands." }
WordHunterWoW_QuestEN[4985] = { title = "The Wildlife Suffers Too", description = "To the east of where we are, near where the Eastern Plaguelands begin, once proud and majestic grizzlies roamed the countryside.  The plague released by the Scourge has sundered these beasts too.  They wander the countryside, agonized by the stiffening of their muscles and the rotting of their fur and flesh.\n\nI ask of you to end their misery as well.  The only cure for their suffering is a swift death, one that must be ministered by your hand.", objectives = "Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands." }
WordHunterWoW_QuestEN[4986] = { title = "Glyphed Oaken Branch", description = "The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark.\n\nAs you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of the Teldrassil tree enters your mind - Darnassus specifically - and the words \"Cenarion Circle\" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.", objectives = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance." }
WordHunterWoW_QuestEN[4987] = { title = "Glyphed Oaken Branch", description = "The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch.  Examining the branch reveals glyphs of a druidic nature carved into the bark.\n\nAs you grasp the branch, you notice it is warm to the touch, more than it should be.  The image of Thunder Bluff in Mulgore enters your mind - Elder Rise specifically - and the words \"Cenarion Circle\" are on the tip of your tongue.  It would appear that the suggestion of where to take the branch has been placed within it.", objectives = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Thunder Bluff is the next step the tauren druid sought. Seek one of the druids there for assistance." }
WordHunterWoW_QuestEN[5001] = { title = "Bijou's Belongings", description = "Ordinarily I don't deal with <race>s but it seems that I'm stuck between a troll and a hard place. You see, my mission here is one of utmost importance to the Horde. The information I've discovered, however, applies to the well being of the Alliance as well. Now believe me, I'm no Alliance sympathizer, but the Blackrock threat is bigger than just a bunch of orcs.\n\nYou help me out by finding my belongings and I'll help you out with some information that could prove useful to your kind.\n\nDeal?", objectives = "Find Bijou's Belongings and return them to her. Good luck!" }
WordHunterWoW_QuestEN[5002] = { title = "Message to Maxwell", description = "I'm a goblin of my word, <race>. Now listen closely:\n\nThese orcs are used primarily as beasts of burden and cannon fodder for the black dragonflight!\n\nTheir true leader is none other than Nefarian, brood of Deathwing. I've also discovered the location of Nefarian's subordinates in this part of the citadel.\n\nTake this map to Marshal Maxwell in the Burning Steppes. It has the location of these fiends marked for easy identification.", objectives = "Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell." }
WordHunterWoW_QuestEN[5021] = { title = "Better Late Than Never", description = "\"The package must be delivered... delivered before I'm trapped here!\"\n\nThe cries of a panicked woman feel almost like a whisper floating through the house.  Cowered in the upstairs corner is the apparition of a woman.  She does not seem to be fully cognizant of her surroundings, and she is only vaguely aware of you.\n\n\"Are you here to deliver my package?  Please, before it gets much worse!  I was going to ride out of here.  It should still be by my horse... or am I too late?\"", objectives = "The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible." }
WordHunterWoW_QuestEN[5022] = { title = "Better Late Than Never", description = "You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to an Emma Felstone of Stormwind; the delivery of the package is dated for well over four years ago.\n\nThough it is unclear if Emma Felstone is even alive, it is widely known that the Stormwind City Hall keep records on the populace of the city.  This is handled through the Royal Factors of the Stormwind Census.", objectives = "Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone. There is usually a census officer located in City Hall." }
WordHunterWoW_QuestEN[5023] = { title = "Better Late Than Never", description = "You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to a Jeremiah Felstone of Lordaeron; the delivery of the package is dated for well over four years ago.\n\nThough it is unclear if Jeremiah Felstone is even alive, it is widely known that the Undercity, formerly known as Lordaeron, keeps records on the populace of the city.  This is handled through the Royal Overseers of the Undercity Census.", objectives = "Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone. There is usually a census officer located near guild and tabard registration." }
WordHunterWoW_QuestEN[5041] = { title = "Supplies for the Crossroads", description = "Whatever has happened in Southern Barrens is causing some of the quilboar tribes to flee our direction. The displaced Razormane in particular grow desperate, and their attacks grow bolder. I've lost two caravans this week alone!\n\nOur warriors at the Crossroads desperately need those supplies, and I'm not about to let the quilboar grow fat off of their misdeeds. Find the missing supply crates and bring them to me. I'd search the quilboar hovel south of here, along the river.", objectives = "Find and return Crossroads' Supply Crates to Thork in the Barrens." }
WordHunterWoW_QuestEN[5042] = { title = "Agamaggan's Strength", description = "", objectives = "" }
WordHunterWoW_QuestEN[5043] = { title = "Agamaggan's Agility", description = "", objectives = "" }
WordHunterWoW_QuestEN[5044] = { title = "Wisdom of Agamaggan", description = "", objectives = "" }
WordHunterWoW_QuestEN[5045] = { title = "Rising Spirit", description = "", objectives = "" }
WordHunterWoW_QuestEN[5046] = { title = "Razorhide", description = "", objectives = "" }
WordHunterWoW_QuestEN[5047] = { title = "Finkle Einhorn, At Your Service!", description = "You'll find Malyfous Darkhammer in Everlook, <class>. Tell him that 'Finkle is A-OK' and that the suit works perfectly.\n\nThen hand him this:\n\n<Finkle hands you a glowing piece of flesh.>\n\nI snatched it from the beast's innards during my 'vacation.'\n\nI bet Malyfous could give you a fairly accurate assessment of what he can do with parts from a monster like this!\n\nOh, I suppose you don't know where Everlook is, do you? To Winterspring, <fella/lady>!", objectives = "Talk to Malyfous Darkhammer in Everlook." }
WordHunterWoW_QuestEN[5048] = { title = "Good Natured Emma", description = "She's a tad ornery, and quite possibly out of her gourd... but the records indicate that Ol' Emma does fit the framework of who Emma Felstone might be.\n\nPerhaps you've seen Ol' Emma wander the city - she talks to herself, most often in nonsensical jibber-jabber.  Still, she doesn't hurt anything or anyone, so folks pretty much leave her be.\n\nAll things considered, I would say that Ol' Emma is in fact Emma Felstone.  You might try asking if her last name is indeed Felstone.", objectives = "Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone. If she is, then perhaps she'd like the package Janice Felstone made for her." }
WordHunterWoW_QuestEN[5049] = { title = "The Jeremiah Blues", description = "From the evidence I am able to muster, the person you seek - and the intended recipient of the parcel - is Jeremiah Payson, the Undercity cockroach vendor.\n\nI've always been of the opinion that it takes a special gift to sell... cockroaches.  No doubt you are on quite the epic sojourn now, mighty <class>.  I will leave you to your world-shaping endeavors.  Allow me, however, to be a part of your magnum opus and reveal that he is located near the bank, suitably groveling under one of the walkways.", objectives = "Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone. If he is, then perhaps he'd like the package Janice Felstone made for him." }
WordHunterWoW_QuestEN[5050] = { title = "Good Luck Charm", description = "It would seem that I was wrong about you <name>, and for that I owe you an apology.  My sister sent me a number of personal effects, including humorously enough the deed to the Felstone farm.  I think I'll pass on reclaiming it right now.\n\nIf my sister's spirit remains tethered to the farm and cannot rest, please... could you return this to her?  It is half of a good luck charm she had, with her husband having the other half.\n\nMaybe her knowing I have these things will now put her soul to rest.", objectives = "Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm." }
WordHunterWoW_QuestEN[5051] = { title = "Two Halves Become One", description = "The ramblings of the poor ghost continue:\n\n\"I'm so cold, John.  Bring me your charm, and we'll be together!  Quickly John, before the plague comes to change us into hideous beasts!  I can't see you John... but I know you're near.  I feel you near me.\"\n\nPerhaps if the second half of the charm was found and reassembled, this would constitute what the spirit of Janice Felstone is seeking.", objectives = "Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.\nGive the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands." }
WordHunterWoW_QuestEN[5052] = { title = "Blood Shards of Agamaggan", description = "Along with the thorns, the blood affected <snort> other aspects of the earth: blood red stones mixed in with other minerals. The Bristleback dig up these shards and carry them as totems <snort> for strength in battle and as totems for their magics. <snort>\n\nI know the secrets of that magic.\n\nBring Mangletooth one of these blood shards to show you understand. Bring Mangletooth many of the shards, and he will bless you with quilboar magic--the magic of Agamaggan! <snort>", objectives = "Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.\nCollect more Blood Shards if you want him to bless you with Agamaggan's power." }
WordHunterWoW_QuestEN[5054] = { title = "Ursius of the Shardtooth", description = "In the snowy mountains of Winterspring, to the northwest, a skilled hunter stalks his prey... I speak of Ursius of the shardtooth bears, an agile and clever beast.\n\nI send you now against him. He roams the sloping hills to the northwest of Everlook. Find and hunt him, before he discovers your intent.\n\nAll that have gone up against Ursius have quickly found themselves to be the prey, and he, the hunter. Stay on your guard.", objectives = "Storm Shadowhoof at Everlook in Winterspring wants you to kill Ursius." }
WordHunterWoW_QuestEN[5055] = { title = "Brumeran of the Chillwind", description = "Swift, and clever, Brumeran glides silently across the snowy landscape of southern Winterspring. But do not let her graceful appearance convince you that she is harmless. All that cross her pay considerably, and often with their own lives.\n\nSeek out Brumeran of the chillwind among the chimera. Defeat her, then return again to me.", objectives = "Storm Shadowhoof at Everlook in Winterspring wants you to kill Brumeran." }
WordHunterWoW_QuestEN[5056] = { title = "Shy-Rotam", description = "In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam. Defeating the matriarch of the frostsabers would grant you much respect in the eyes of your fellow <race>.\n\nGo again to the harsh wilds, and once there, gather sacred meat from the frostsabers. Find the stone of Shy-Rotam, and place it there. Placing the meat of her kin before her will summon Shy-Rotam, in anger.\n\nBe ready for her fury, and defeat her.", objectives = "Storm Shadowhoof at Everlook in Winterspring wants you to defeat Shy-Rotam." }
WordHunterWoW_QuestEN[5057] = { title = "Past Endeavors", description = "Before you spoke to me, <name>, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a <class>, and I now know these things to be the truth.\n\nThose that excel as you do are worthy of recognition. Take this marker to a friend of mine in Thunder Bluff named Melor Stonehoof. I'm sure he will remember you, and what you accomplished so long ago. Speak to him of you recent victories, and do not ever forget what you have accomplished today.", objectives = "Bring Storm Shadowhoof's Marker to Melor Stonehoof in Thunder Bluff." }
WordHunterWoW_QuestEN[5058] = { title = "Mrs. Dalson's Diary", description = "", objectives = "" }
WordHunterWoW_QuestEN[5059] = { title = "Locked Away", description = "", objectives = "" }
WordHunterWoW_QuestEN[5060] = { title = "Locked Away", description = "", objectives = "" }
WordHunterWoW_QuestEN[5061] = { title = "Aquatic Form", description = "You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Mathrengyl Bearwalker, in Darnassus.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.\n\nGoodbye, young druid.  We shall speak again.You will receive:", objectives = "Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion." }
WordHunterWoW_QuestEN[5062] = { title = "Sacred Fire", description = "Arikara is a deadly creature that must be dealt with swiftly. In order to hunt her down you will need to light the sacred fire of life - this will summon Arikara.\n\nGo now and harvest the rare Incendia agave plant. Once you have harvested enough agave, seek council with Magatha Grimtotem on Elder Rise in Thunder Bluff. She is a powerful shaman that can enchant the agave plant to create a powder that will light the fire.\n\nTravel northeast to the Boiling Pool and gather Incendia agave.", objectives = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff." }
WordHunterWoW_QuestEN[5063] = { title = "Cap of the Scarlet Savant", description = "A finer cap you may never see. From the pristine hide of the beast, our expert crafters will create the most phenomenal hat a prestidigitator could ever hope to don!\n\nFifty gold pieces along with the listed items and your head shall be graced with the Cap of the Scarlet Savant:\n\n*The pristine hide of the beast.\n\n*Frayed abomination stitchings.\n\n*Arcane crystals.\n\n*Enchanted scarlet thread.\n\nBEHOLD!You will receive:", objectives = "In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread. \nYou will also be required to pay 50 gold pieces for the crafting of the item." }
WordHunterWoW_QuestEN[5064] = { title = "Grimtotem Spying", description = "<name>, you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks. We discovered that separate chests in Darkcloud Pinnacle hold these guarded messages.\n\n<name>, if you succeed in this dangerous mission, I will reward you in kind.", objectives = "Locate and retrieve the three Secret Notes in Darkcloud Pinnacle." }
WordHunterWoW_QuestEN[5065] = { title = "The Lost Tablets of Mosh'aru", description = "The troll with whom you spoke did not tell the truth.  The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend.  I have studied long, and found that there are six Tablets of Mosh'aru, not two!  Six!\n\nAnd I fear that we will not like what secrets the others hold..\n\nFind the third and fourth tablets of Mosh'aru.  They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me.", objectives = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris." }
WordHunterWoW_QuestEN[5066] = { title = "A Call to Arms: The Plaguelands!", description = "Hear ye, hear ye!  All heroes are called upon to heed these words!\n\nA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!\n\nHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!", objectives = "Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains." }
WordHunterWoW_QuestEN[5067] = { title = "Leggings of Arcana", description = "While the crafting of such an item has never successfully been accomplished, it is thought to be possible - under the right circumstance.\n\nShould the seeker of arcanum desire to imbue leggings with immense power, the following they must find:\n\n* The pristine hide of the Beast.\n\n* Frayed abomination stitchings.\n\n*Arcanite Bars.\n\n*Frostwhisper's embalming fluid.\n\nBEHOLD!You will receive:", objectives = "In order to create the Leggings of Arcana, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid.\nYou will also be required to pay 50 gold pieces for the crafting of the item." }
WordHunterWoW_QuestEN[5068] = { title = "Breastplate of Bloodthirst", description = "It is said that only one Breastplate of Bloodthirst has ever been created and that it was made for the legendary assassin, Garona. Whether this world will ever see another is doubtful.\n\nRegardless! Our master crafters can reproduce the item given the necessary components:\n\n*The pristine hide of the Beast.\n\n*Frayed abomination stitchings.\n\n*Arcanite bars.\n\n*The skin of shadow.\n\nBEHOLD!You will receive:", objectives = "In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.\nYou will also be required to pay 50 gold pieces for the crafting of the item." }
WordHunterWoW_QuestEN[5081] = { title = "Maxwell's Mission", description = "This information fills in the gaps to our otherwise impeccable intelligence of Blackrock Spire.\n\nThe attack must be decisive, <name>.\n\nFirst their war master, the troll Voone, must be destroyed. Without his battle plans, the Blackrock orcs will be thrown into chaos.\n\nYou must then take out the ogre Highlord, Omokk. The cowardly ogres of Blackrock are powerless without his leadership.\n\nLastly, the overlord of the citadel: Wyrmthalak. With Wyrmthalak dead, their central command unit is without a conduit.", objectives = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done." }
WordHunterWoW_QuestEN[5082] = { title = "Threat of the Winterfall", description = "I came to Winterspring to investigate the Frostfire Hot Springs. I've noticed that the water seems to have ...strange qualities. I haven't yet been able to discover the source, and to tell you the truth, I've had some difficulty lately, due to the Winterfall furbolg.\n\nThey seem to be drawn to the springs, just as I am. They have become extremely protective of the water, and won't let me come near the two larger springs to the north of here.\n\nI'd like to continue my studies, so won't you help me?", objectives = "Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics." }
WordHunterWoW_QuestEN[5083] = { title = "Winterfall Firewater", description = "This vial that you picked up from the Winterfall furbolg is empty, but you can detect a few drops of a strange green liquid inside; it almost glows.\n\nIs it something important?\n\nDonova Snowden would probably be able to tell you more, since she has been camped by the hot springs in Winterspring for some time now.", objectives = "Bring the Empty Firewater Flask to Donova Snowden in Winterspring." }
WordHunterWoW_QuestEN[5084] = { title = "Falling to Corruption", description = "This greenish liquid... it reminds me a bit of the sludge I saw when traveling through Felwood. And I have seen some Winterfall Runners passing into Timbermaw... Perhaps these things have something to do with the flask you found, <name>.\n\nThere is a large group of furbolg just past Timbermaw Hold, in Felwood. Called the Deadwood tribe, they have been corrupted and driven mad by the fel. Why don't you look around there and see if you can find any evidence of dealings between the Winterfall and the Deadwood?", objectives = "Search the Deadwood furbolg camp in northern Felwood for a clue." }
WordHunterWoW_QuestEN[5085] = { title = "Mystery Goo", description = "The greenish substance inside the cauldron appears to be similar to what you found in the flask. This strange gooey stuff could be as corrupted as the furbolg that created it...\n\nIf the Winterfall furbolg are using it, does this mean that they will soon be as corrupted as the Deadwood tribe?\n\nIt would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron.", objectives = "Report back to Donova Snowden with your findings." }
WordHunterWoW_QuestEN[5086] = { title = "Toxic Horrors", description = "I've studied the sample you returned with, and while I can't say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison.\n\nI believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors.\n\nCollect a few samples for me to compare, but be careful -- it's very dangerous there!", objectives = "Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring." }
WordHunterWoW_QuestEN[5087] = { title = "Winterfall Runners", description = "Very interesting, <name>...\n\nWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.\n\nWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment.", objectives = "Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village." }
WordHunterWoW_QuestEN[5088] = { title = "Arikara", description = "Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead.\n\nThe enchantment that I have weaved into the Incendia powder will summon Arikara to you, <name>.\n\nI fear she may be stalking Cairne Bloodhoof; too much Tauren lore has changed, and I fear this has angered Arikara. Move quickly before all is lost, <class>!", objectives = "Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed." }
WordHunterWoW_QuestEN[5089] = { title = "General Drakkisath's Command", description = "From the corpse of the defeated serpent you uncover what appears to be a note of some importance: A letter from his superior, General Drakkisath, concerning protocol.\n\nYour instinct tells you that you should take it to Marshal Maxwell.", objectives = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes." }
WordHunterWoW_QuestEN[5090] = { title = "A Call to Arms: The Plaguelands!", description = "Hear ye, hear ye!  All heroes are called upon to heed these words!\n\nA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!\n\nHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!", objectives = "Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains." }
WordHunterWoW_QuestEN[5091] = { title = "A Call to Arms: The Plaguelands!", description = "Hear ye, hear ye!  All heroes are called upon to heed these words!\n\nA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!\n\nHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!", objectives = "Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains." }
WordHunterWoW_QuestEN[5092] = { title = "Clear the Way", description = "With Andorhal's western and northern roads into the city well fortified, I'm looking to strike at it from the less defended eastern road.  The Scourge relies on the buffer of undead that infests Sorrow Hill as a first line of defense.  If we are to advance on Andorhal, we will need to do it through Sorrow Hill.\n\nYour first assignment will be to clear the way through Sorrow Hill.  Thin out the skeletons and ghouls that haunt the area; report back to me when this is done!", objectives = "Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.\nReturn to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5093] = { title = "A Call to Arms: The Plaguelands!", description = "Heroes of the realm, hear me - the Horde calls upon you for swift action!\n\nA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!\n\nHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!", objectives = "Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity." }
WordHunterWoW_QuestEN[5094] = { title = "A Call to Arms: The Plaguelands!", description = "Heroes of the realm, hear me - the Horde calls upon you for swift action!\n\nA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!\n\nHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!", objectives = "Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity." }
WordHunterWoW_QuestEN[5095] = { title = "A Call to Arms: The Plaguelands!", description = "Heroes of the realm, hear me - the Horde calls upon you for swift action!\n\nA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!\n\nHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glades!", objectives = "Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glades and the Undercity." }
WordHunterWoW_QuestEN[5096] = { title = "Scarlet Diversions", description = "Before Andorhal, we must tackle the advancing Scarlet Crusade menace from Hearthglen.  They've made camp between Felstone Field and Dalson's Tears, making us risk conflict against both the Scourge and the Crusade at once.\n\nMy plan is to play them off of each other by sending you to destroy the command tent they've set up; use some Flame in a Bottle from this box of incendiaries.  Once razed, plant this Scourge banner by the tent.  With some luck, they'll ignore us and focus on the Scourge for vengeance.", objectives = "Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.\nPlace the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5097] = { title = "All Along the Watchtowers", description = "Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.\n\nYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!", objectives = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\nOnce all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5098] = { title = "All Along the Watchtowers", description = "Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.\n\nYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!", objectives = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\nOnce all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5102] = { title = "General Drakkisath's Demise", description = "We battle against these beasts on two fronts: From our capital of Stormwind we fight them from the inside out and here, in the Burning Steppes, we take the battle to their doorstep. We must be vigilant, <name>. None should be spared our wrath as none of our own were spared when they struck at our homes and families.\n\nFind this General Drakkisath and destroy him!\n\nThe task certainly will not be a simple one, but the rewards shall be extravagant.", objectives = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done." }
WordHunterWoW_QuestEN[5103] = { title = "Hot Fiery Death", description = "The only thing that remains of this human are some charred bones. He seems to have died within arms reach of what he was after - unfired plate gauntlets.\n\nPerhaps you should grab the gauntlets and get out of the fire?", objectives = "Someone in this world must know what to do with these gauntlets. Good luck!" }
WordHunterWoW_QuestEN[5121] = { title = "High Chief Winterfall", description = "While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand.\n\nThe Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but I think that if their leader is slain, they will not get any worse.\n\nHead east to Winterfall Village.", objectives = "Donova Snowden in Winterspring wants you to defeat High Chief Winterfall." }
WordHunterWoW_QuestEN[5122] = { title = "The Medallion of Faith", description = "", objectives = "" }
WordHunterWoW_QuestEN[5123] = { title = "The Final Piece", description = "The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them.\n\nBut perhaps Donova will be able to tell you what it says...", objectives = "Bring the Crudely-written Log to Donova Snowden in Winterspring." }
WordHunterWoW_QuestEN[5124] = { title = "Fiery Plate Gauntlets", description = "By Thaurissan's beard!\n\nWhere did you find them?\n\nMore importantly, are you willing to part with them? Naturally, I would pay you for such a noble gesture.\n\nI'll tell you what, <name>. If you give me those unfired gauntlets, I will teach you how to make a set all your own. All you need to do is collect the parts for me so that I may narrow down the exact recipe.\n\nDo we have a deal??\n\nHere's the list of what I need, I'll front the non-enchanted thorium myself since you're supplying the gauntlets.", objectives = "Bring Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire, and 4 Star Rubies. You will also need to turn in your Unfired Plate Gauntlets." }
WordHunterWoW_QuestEN[5125] = { title = "Aurius' Reckoning", description = "", objectives = "" }
WordHunterWoW_QuestEN[5126] = { title = "Lorax's Tale", description = "The Satyr paces about and talks to himself. Do you wish to question him?", objectives = "Speak with Lorax. Listen to what he has to say." }
WordHunterWoW_QuestEN[5127] = { title = "The Demon Forge", description = "Lorax makes deals, he does not accept them from insignificant mortals.\n\nA deal I shall make with you, however... take this pike, it is imbued with powerful Fel energies. When you find Goraluk Anvilcrack, slay him and drive this pike through his dying heart. His soul he bartered, his soul I shall have. Return the pike and return the breastplate that the thief stole and I shall teach you what it is that he was to learn.", objectives = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\nYou must also find the Unforged Rune Covered Breastplate.\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring." }
WordHunterWoW_QuestEN[5128] = { title = "Words of the High Chief", description = "The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper.\n\nHe is part of a group known as the Emerald Circle, druids that are committed to their work in Felwood, healing the land from the corruption.\n\nKelek has much experience with the furbolgs in Felwood, and may be able to tell you more about the log.\n\nThank you, again, <name>.", objectives = "Take the Crudely-written Log to Kelek Skykeeper in southern Felwood." }
WordHunterWoW_QuestEN[5141] = { title = "Dragonscale Leatherworking", description = "Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.\n\nBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.Upon completion of this quest you will gain:", objectives = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Peter Galen in Azshara.\nCompleting this quest will give you access to the Dragonscale Leatherworking arts.\nThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so." }
WordHunterWoW_QuestEN[5142] = { title = "Little Pamela", description = "So many of us died at the battle of Darrowshire.  So many died... and worse.\n\nWhen the battle began I hid my niece Pamela, and I do not know what happened to her.  I am but a wandering spirit, but my heart still longs to know Pamela's fate.\n\nPlease, good <class>.  Will you go to Darrowshire and search for her?  It is to the east, beyond Gahrron's Withering.", objectives = "Find Pamela Redpath." }
WordHunterWoW_QuestEN[5143] = { title = "Tribal Leatherworking", description = "To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.\n\nKnow this, <class>: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.Upon completion of this quest you will gain:", objectives = "Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.\nCompleting this quest will give you access to the Tribal Leatherworking arts.\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so." }
WordHunterWoW_QuestEN[5144] = { title = "Elemental Leatherworking", description = "Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.\n\nKnow this, <class>: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.Upon completion of this quest you will gain:", objectives = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge.\nCompleting this quest will give you access to the Elemental Leatherworking arts.\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so." }
WordHunterWoW_QuestEN[5145] = { title = "Dragonscale Leatherworking", description = "Dragonscale leatherworking isn't easy, but it's extremely rewarding.  I'll teach you how to make this fine mail armor, but only if you agree to certain conditions.\n\nBy choosing this path, you agree never to learn elemental or tribal leatherworking; there is only room for one of the three at the apex of the craft.  Furthermore, I'll need some samples of your best work involving scorpid armor.  Finally, I'll need proof of your ability to acquire the staple of the trade: scales of the dragonkin.Upon completion of this quest you will gain:", objectives = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands.\nCompleting this quest will give you access to the Dragonscale Leatherworking arts.\nThe completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so." }
WordHunterWoW_QuestEN[5146] = { title = "Elemental Leatherworking", description = "Elemental leatherworking is what I know, and if you're willing to open your mind to the greater powers of substance, I will share with you all there is to learn.\n\nKnow this, <class>: by choosing this path you agree never to learn dragonscale or tribal leatherworking; there is only room for practice of one of the three arts.  Furthermore, I'll need adequate proof that you are in tune with the elements of nature; to that end, bring me the purest essences of fire, water, earth, and wind.Upon completion of this quest you will gain:", objectives = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains.\nCompleting this quest will give you access to the Elemental Leatherworking arts.\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so." }
WordHunterWoW_QuestEN[5147] = { title = "Wanted - Arnak Grimtotem", description = "Wanted: Arnak Grimtotem\n\nArnak the outcast is wanted for the heinous crimes of murder and kidnapping. Handsome rewards will be given to those brave enough to bring this criminal to justice.\n\nArnak was last seen on the cliffs near the Darkcloud Pinnacle. Show the proof of your deed to Cliffwatcher Longhorn in Freewind Post in order to claim the reward.", objectives = "Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post." }
WordHunterWoW_QuestEN[5148] = { title = "Tribal Leatherworking", description = "To learn tribal leatherworking demands an understanding of how primal nature truly is; I know that you have already mastered the art of making wild leather armor, and I am willing to complete your training.\n\nKnow this, <class>: by choosing this path you agree never to learn dragonscale or elemental leatherworking; there is only room for practice of one of the three arts.  Furthermore, bring to me the finest samples of your wild leather armor.  From there, we will begin your mastery.Upon completion of this quest you will gain:", objectives = "Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale.\nCompleting this quest will give you access to the Tribal Leatherworking arts.\nThe completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so." }
WordHunterWoW_QuestEN[5149] = { title = "Pamela's Doll", description = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!\n\nBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!\n\nAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.\n\nWill you find my doll for me?", objectives = "Find Pamela's doll." }
WordHunterWoW_QuestEN[5150] = { title = "Dadanga is Hungry!", description = "", objectives = "" }
WordHunterWoW_QuestEN[5151] = { title = "Hypercapacitor Gizmo", description = "I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck. Hah! Even the centaur tremble in the presence of this ferocious beast!\n\nHere is the key to the cage. They took everything there, but left him alone. Slay this beast and bring back my hypercapacitor, and I shall reward you.\n\nThe wrecked caravan is just north of here.", objectives = "Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner." }
WordHunterWoW_QuestEN[5152] = { title = "Auntie Marlene", description = "Oh, I'm so lonely!  Where is my family?  Auntie Marlene told me to stay here, but then she left and never came back!  And my dad... have you seen him?\n\nMaybe Auntie Marlene knows where he is.  She lives near Andorhal, in a house to the south.  I think it was on a hill... she said it was on a hill.\n\nPlease, <name>.  You're my new friend!  Will you talk to my Auntie for me?", objectives = "Speak with Marlene, south of the Ruins of Andorhal." }
WordHunterWoW_QuestEN[5153] = { title = "A Strange Historian", description = "I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.  Oh, he is doomed!\n\nBut perhaps we can change his fate.\n\nSearch the graves outside for Joseph's monument.  His body's not there, for it was trampled and destroyed years ago, but under the monument is his wedding ring.  Take that ring to Chromie... a strange gnome with very strange powers.\n\nChromie is staying in the ruined inn at the northwest corner of Andorhal.", objectives = "Bring Joseph's Wedding Ring to Chromie." }
WordHunterWoW_QuestEN[5154] = { title = "The Annals of Darrowshire", description = "To save Joseph Redpath, we must first discover his past.  We can learn this in the Annals of Darrowshire, a book held in the city hall of Andorhal.\n\nBring me that book.  We can then learn Joseph's fate, and with luck... change it!", objectives = "Bring the Annals of Darrowshire to Chromie in Andorhal." }
WordHunterWoW_QuestEN[5155] = { title = "Forces of Jaedenar", description = "If I am to trust you in this matter, you will first have to prove yourself.\n\nI must know that you are an enemy of the Shadow Council--the ones responsible for many evils here and abroad.\n\nTravel deeper into Felwood. To the west you will see a path leading to Jaedenar. It is there that the Council plots with the Burning Legion.\n\nEnter the depths of one of the corrupted Barrow Dens they inhabit and slay their kind. Return to me after you've done this. Then I will know you truly seek to help us.", objectives = "Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood." }
WordHunterWoW_QuestEN[5156] = { title = "Verifying the Corruption", description = "To the north, along the east of the road in what's called Shatter Scar Vale, is an area where infernals were called down during the last great war--the craters still scar the land, as do the infernals themselves.\n\nI am curious about two things. First, are there still entropic elementals roaming the area? And second, are the craters still filled with the corrupt, fetid water that gathered there years ago? Will you help me and check, <name>? Be careful though, the infernals destroy anything in their path.", objectives = "Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood." }
WordHunterWoW_QuestEN[5157] = { title = "Collection of the Corrupt Water", description = "Deep within Jaedenar lies Shadow Hold--the main fortress of their corruption and evil.\n\nThe Shadow Council has protective spells surrounding their lair in the form of braziers. If I am to find out any more information about our enemy through scrying, then those braziers must be extinguished. By doing so, I should be able to spy on the Council and find out who leads them.\n\nIf you can, take this canteen and fill it at the Moon Well in the center of Jaedenar. Return to me afterwards.", objectives = "Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood." }
WordHunterWoW_QuestEN[5158] = { title = "Seeking Spiritual Aid", description = "Take the corrupt water to the Barrens, <name>. South of Ratchet, hidden along the shore, is an old friend of mine, a shaman named Islen Waterseer. She is a powerful shaman who will help us. Her relationship with the spirits of water has always been strong. Our task being a noble one should be enough to persuade her and the spirits of water to aid us in this task.\n\nYou should find her at a small camp right along the water's edge. And, <name>, ignore the pirates... they are but a nuisance and no threat to you.", objectives = "Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens." }
WordHunterWoW_QuestEN[5159] = { title = "Cleansed Water Returns to Felwood", description = "Thank the spirits, <name>. They are the ones that have come to your aid, not me.\n\nI give this purified water to you now. Please give my regards to Greta and my best wishes. She is tackling something greater than many of us... as I'm sure she will soon find out.\n\nThe Shadow Council is not a force to be trifled with, <name>. Remember that.\n\nGo now. Take the water and return to Greta.", objectives = "Take the Purified Moon Well Water to Greta Mosshoof in Felwood." }
WordHunterWoW_QuestEN[5160] = { title = "The Matron Protectorate", description = "Travel to Kalimdor, <race>. Our flight makes its home in the frigid landscape of Winterspring. Once you reach Winterspring, find the caves of Mazthoril.\n\nUpon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to Haleh, our matron protectorate.\n\nGive her the scale so that she may scry what it is I have seen and felt, here in this doomed place.", objectives = "Travel to Winterspring and find Haleh. Give her Awbee's scale." }
WordHunterWoW_QuestEN[5161] = { title = "Wrath of the Blue Flight", description = "We understand what the cursed brood of Deathwing attempts to do and we know that it cannot be allowed.\n\nBecause of the protection Blackrock mountain affords Nefarian, it has become increasingly difficult for us to intercede.\n\nWe can, however, empower you, mortal - should you so choose.\n\nThe path before you is one full of peril. You must decide whether to accept our help. Ponder this and speak with me again when a decision has been made.", objectives = "Speak with Haleh if you wish to continue." }
WordHunterWoW_QuestEN[5162] = { title = "Wrath of the Blue Flight", description = "It is the arcane that I control and the arcane which will send you to your next destination.\n\nWhen you are ready, the journey will begin. To the Plaguelands you will go and to Jeziba you will speak.\n\nHe is a mortal as wise as the ancients and as patient as the immovable earth. Find him in Andorhal.", objectives = "Speak with Jeziba in the Plaguelands. He resides in Andorhal." }
WordHunterWoW_QuestEN[5163] = { title = "Are We There, Yeti?", description = "It's all ready, <name>!\n\nNow, I sent some mail to my friends already, telling them that I have a surprise for them. This is where you come in!\n\nI'm going to give you my mechanical yeti, and you need to surprise them by paying each of my friends a visit, turning the yeti on and sending it towards them.\n\n Once you have shown Legacki in Everlook, Sprinkle in Gadgetzan, and Quixxil in Marshal's Refuge, come back and tell me what happened!\n\nPlease bring my yeti back to me then, too.", objectives = "Take Umi's Mechanical Yeti and scare her friends with it:\nLegacki in Everlook (Winterspring)\nSprinkle in Gadgetzan (Tanaris)\nQuixxil in Marshal's Refuge (Un'Goro Crater)\nWhen you are done, bring the Mechanical Yeti back to Umi." }
WordHunterWoW_QuestEN[5164] = { title = "Catalogue of the Wayward", description = "A finer instrument of justice, Haleh could not have chosen. Read from the catalogue of the wayward and be enlightened.\n\nShould you persist... should you do what is asked of you... should you survive... a hero you will make.", objectives = "Read from the Catalogue of the Wayward." }
WordHunterWoW_QuestEN[5165] = { title = "Dousing the Flames of Protection", description = "Now, you must return to Jaedenar. The braziers are more than likely spread throughout Shadow Hold. Douse each of their flames and the protections the Council has set up will fall for at least a short period of time. I will be waiting for that to happen. When it does, I will look deep within the Hold and try to find out who the head of this beast is. Then, and only then, will we see about attacking them directly.", objectives = "Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary." }
WordHunterWoW_QuestEN[5166] = { title = "Breastplate of the Chromatic Flight", description = "The forging of a powerful breastplate to protect against the unrelenting attacks of the chromatic flight is one built upon irony.\n\nThe scales of the very beasts we battle must be sewn to the pristine carapace of an elder chromatic drake or dragon. None are known to exist at this time and we should hope that none will ever exist.\n\nLastly, perhaps the most difficult of all components: the blood of heroes.\n\nThe Sculptor must ultimately forge this creation.You will receive:", objectives = "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':\n1 Chromatic Carapace.\n10 Brilliant Chromatic Scales.\n10 Blood of Heroes.\n10 Frayed Abomination Stitchings." }
WordHunterWoW_QuestEN[5167] = { title = "Legplates of the Chromatic Defier", description = "The carapace of a mature chromatic drake is needed to form the foundation of the leggings. Brilliant chromatic scales are then layered upon the wire frame and enchanted in the blood of heroes. Finally, the supple skin of shadow must be applied to the inner greaves.Upon completion of this quest you will gain:", objectives = "To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':\n1 Chromatic Carapace.\n10 Brilliant Chromatic Scales.\n10 Blood of Heroes.\n5 Skin of Shadow." }
WordHunterWoW_QuestEN[5168] = { title = "Heroes of Darrowshire", description = "The heroes of Darrowshire hold a place in my heart, and the book you brought me, the Annals of Darrowshire, tells their tales.\n\nIt tells of the paladin Davil Lightfire and how the Crusade took his libram to the town hall of Hearthglen.\n\nIts passages also speak of my brother, Captain Redpath.  After his betrayal, his shield was cracked and discarded and now lies in the most unlikely of places -- near the barn of Gahrron's Withering.\n\nGather these relics, <name>.  For fate and tragedy surrounds them.", objectives = "Bring Davil's Libram and Redpath's Shield to Carlin Redpath." }
WordHunterWoW_QuestEN[5181] = { title = "Villains of Darrowshire", description = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  His body was cast into a lake, northwest of Corin's Crossing, and his skull remains there.\n\nMarduk the Black was never defeated, but his fabled sword was shattered and lost.  It lies at the bottom of the gorge west of Corin's Crossing.\n\nRetrieve these items, <name>.  I know not why, but I am certain their fate lies with you.", objectives = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel." }
WordHunterWoW_QuestEN[5201] = { title = "Winterfall Intrusion", description = "My presence goes unnoticed by most, <name>. However, there is an annoyance that seems firmly rooted here in Winterspring: the Winterfall furbolg.\n\nAlthough I have never directly attacked the furbolg, they seem crazed, fearful of anything in their path. I have watched them slay countless creatures that had the misfortune to simply be in the wrong place at the wrong time.\n\nI am weary of their meddling -- please, help me by fighting back. Slay the furbolg and keep them away from Frostsaber Rock.", objectives = "Rivern Frostwind wants you to slay 5 Winterfall Shaman and 5 Winterfall Ursa." }
WordHunterWoW_QuestEN[5202] = { title = "A Strange Red Key", description = "The small red key seems to be made of some kind of bone material. It is heavy in your hand, but appears very fragile. Why would a member of the Shadow Council have such a thing? Perhaps there is something within Jaedenar that this strange key unlocks.", objectives = "Search through Jaedenar to discover what the Blood Red Key is used for." }
WordHunterWoW_QuestEN[5203] = { title = "Rescue From Jaedenar", description = "But, as much as it pains me, there is one thing that must be done first: I have to find Trey's sword Lightforge and escape Shadow Hold to tell my superiors what's happening here. Can you help me, <name>?\n\nOur equipment isn't far from here, and you've already proven you can survive the path to the top.\n\nAfter we escape, I'll head to Darnassus if you can find my friend Jessir near the Ashenvale border. She was to meet us at the Emerald Circle's camp near there.\n\nWhat do you say, <name>? Can you help me again?", objectives = "Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends." }
WordHunterWoW_QuestEN[5204] = { title = "Retribution of the Light", description = "", objectives = "Return to Jaedenar and kill the succubus Rakaiah before finding the Remains of Trey Lightforge." }
WordHunterWoW_QuestEN[5206] = { title = "Marauders of Darrowshire", description = "Chromie said the relics you gathered are reagents to a powerful spell, and one more is required: skulls from the scourge who took part in the battle of Darrowshire.\n\nTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.\n\nGo, <name>.  You'll find scourge champions in the Noxious Glade to the north and the Fungal Vale to the west.", objectives = "Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands." }
WordHunterWoW_QuestEN[5210] = { title = "Brother Carlin", description = "The Annals of Darrowshire, through my magic, has gained pages at its end, and now it extends its history beyond the battle.  One of the extra passages tells of another Redpath, Carlin, who survived Joseph's betrayal.  Carlin's now in the Plaguelands to the east, at the Light's Hope Chapel.\n\nTake the book and speak with him.", objectives = "Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands." }
WordHunterWoW_QuestEN[5211] = { title = "Defenders of Darrowshire", description = "Many of the defenders fell at the battle of Darrowshire.  And many roam again as the ghastly servants of the Scourge!  Find these poor souls and end their misery!\n\nHunt cannibal ghouls, gibbering ghouls and diseased flayers.  Many of these fiends were once the good folk of Darrowshire and destroying their forms now will set their souls free.\n\nYou will find them in Plaguewood and Corin's Crossing, and in other Scourge strongholds of Eastern Plaguelands.", objectives = "Free 15 Darrowshire Spirits and return to Carlin Redpath." }
WordHunterWoW_QuestEN[5212] = { title = "The Flesh Does Not Lie", description = "The Forsaken apothecaries are not the only beings in this world schooled in the sciences.\n\nI have been studying the plague for years, <race>. We had previously thought that the potency of the plague was dwindling, but what I have discovered here in the Plaguelands is startling. The plague seems to be growing in strength!\n\nI need to run more tests! The most potent source of the plague is from the tainted flesh of the most recently infected. Travel to Stratholme and bring me samples, <name>.", objectives = "Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample." }
WordHunterWoW_QuestEN[5213] = { title = "The Active Agent", description = "You will have to delve deeper into Stratholme, <name>.\n\nBeyond the first gates you will find the ziggurats. We know that the Scourge draws great power from these structures. Search the Ziggurats and return with any information that you may discover.", objectives = "Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink." }
WordHunterWoW_QuestEN[5214] = { title = "The Great Fras Siabi", description = "Terrible thing... what happened to Ezra. You see, the town was sacked and Ezra didn't want to leave his precious goods behind. The last thing I remember him saying was, 'I'll burn every last leaf before they get their damned, dirty hands on them!'\n\nI may love a good stogie but I'm no fool. I left Ezra and his delightful store that day. I assume he went down in flames but if there's a chance that even one box of his famous tobacco is still intact...\n\nWhat do you say, <name>? Find a box for ol' Smokey?", objectives = "Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done." }
WordHunterWoW_QuestEN[5215] = { title = "The Scourge Cauldrons", description = "Within the lands of former Lordaeron are eight cauldrons - four here in the west, and four more ensconced in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.\n\nThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, High Priestess MacDonnell, will be your point on this assignment; she'll continue the briefing from here.", objectives = "Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands." }
WordHunterWoW_QuestEN[5216] = { title = "Target: Felstone Field", description = "Of the four cauldrons here in the west, the one located at Felstone Field may be the easiest one in obtaining access to.  The Scourge have greener troops positioned here, though they should not be underestimated.\n\nGo to Felstone Field, northwest of Andorhal, and engage the cauldron lord there.  We think it has a key that will unlock access to the cauldron.  When unlocked, use this bottle to obtain a sample of the poisons inside the cauldron; we'll need it for study in developing a counter agent.", objectives = "Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5217] = { title = "Return to Chillwind Camp", description = "You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied.\n\nWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.", objectives = "Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5218] = { title = "Felstone Field Cauldron", description = "", objectives = "" }
WordHunterWoW_QuestEN[5219] = { title = "Target: Dalson's Tears", description = "One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  Well, we shall shed no tears this day as we thwart the Scourge and have them choke on their own fumes!\n\nGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you into the cauldron.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses.", objectives = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5220] = { title = "Return to Chillwind Camp", description = "You carefully fill the bottle with enough of the cauldron's ichors for what you consider to be suitably sized sample.\n\nWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.", objectives = "Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5221] = { title = "Dalson's Tears Cauldron", description = "", objectives = "" }
WordHunterWoW_QuestEN[5222] = { title = "Target: Writhing Haunt", description = "Two cauldrons have been successfully opened; while you will be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!\n\nThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.\n\nGood hunting, <name>!", objectives = "Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5223] = { title = "Return to Chillwind Camp", description = "You delicately top off the empty bottle; a sample of the foul substance that churns under the platform of the cauldron now oozes back and forth inside the fragile glass container.\n\nWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.", objectives = "Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5224] = { title = "Writhing Haunt Cauldron", description = "", objectives = "" }
WordHunterWoW_QuestEN[5225] = { title = "Target: Gahrron's Withering", description = "The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, <name>.\n\nGahrron's Withering is due northeast of our position here, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the Light protect you in this dangerous mission, <class>.", objectives = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5226] = { title = "Return to Chillwind Point", description = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission.", objectives = "Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5227] = { title = "Gahrron's Withering Cauldron", description = "", objectives = "" }
WordHunterWoW_QuestEN[5228] = { title = "The Scourge Cauldrons", description = "Within the lands of former Lordaeron are eight cauldrons - four in the west, and four more entrenched in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.\n\nThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, Shadow Priestess Vandis, will be your point on this assignment; she'll continue the briefing from here.", objectives = "Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5229] = { title = "Target: Felstone Field", description = "Of the four cauldrons in the Western Plaguelands, the one at Felstone Field may be the easiest one to gain access to.  The Scourge have greener troops positioned here, though they should not be underestimated.\n\nGo to Felstone Field, due east of here and northwest of Andorhal, and engage the cauldron lord there.  On it is a key that will unlock access to the cauldron.  When unlocked, use this bottle to get a sample of the cauldron's toxins; we'll need it for study in developing a counter agent.", objectives = "Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5230] = { title = "Return to the Bulwark", description = "You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied.\n\nWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.", objectives = "Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5231] = { title = "Target: Dalson's Tears", description = "One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  No tears will be shed this day, <class>; we must strike at this cauldron and gain access to it!\n\nGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you inside the cauldron's innards.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses.", objectives = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5232] = { title = "Return to the Bulwark", description = "You carefully fill the bottle with enough of the cauldron's ichors for what you consider to be suitably sized sample.\n\nWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.", objectives = "Bring the Filled Dalson's Tears Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5233] = { title = "Target: Writhing Haunt", description = "Two cauldrons have been successfully opened; while you'll be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!\n\nThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.\n\nGood hunting, <name>!", objectives = "Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5234] = { title = "Return to the Bulwark", description = "You delicately top off the empty bottle; a sample of the foul substance that churns under the platform of the cauldron now oozes back and forth inside the fragile glass container.\n\nWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.", objectives = "Bring the Filled Writhing Haunt Bottle to Shadow Priestess Vandis at The Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5235] = { title = "Target: Gahrron's Withering", description = "The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, <name>.\n\nGahrron's Withering is far to the east of the Bulwark, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the shadows cloak you in safety for this dangerous mission, <class>.", objectives = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron." }
WordHunterWoW_QuestEN[5236] = { title = "Return to the Bulwark", description = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission.", objectives = "Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5237] = { title = "Mission Accomplished!", description = "", objectives = "" }
WordHunterWoW_QuestEN[5238] = { title = "Mission Accomplished!", description = "", objectives = "" }
WordHunterWoW_QuestEN[5241] = { title = "Uncle Carlin", description = "Sometimes, when it's nighttime, I can hear my Uncle Carlin crying.  It sounds like he's far away, to the east.\n\nI hope he's not crying for me!  <name>, will you find my uncle and tell him I'm alright?\n\nIf you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!", objectives = "Find Carlin Redpath." }
WordHunterWoW_QuestEN[5242] = { title = "A Final Blow", description = "Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside. The straight path down to the bottom is the only way... and I also know who you should seek out. His name is Fel'dan... Shadow Lord Fel'dan. He is the mortal in power down below... he is the head of the serpent. Kill him and his two succubus servants and return to me. Fel'dan is the one making pacts with the Legion. He must be stopped.", objectives = "Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood." }
WordHunterWoW_QuestEN[5243] = { title = "Houses of the Holy", description = "I look at my undeath as a malady, <race>. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?\n\nI am revered by my colleagues because of the sacrifices I have made, but the accolades mean nothing to me.\n\nIf you are interested in assisting the Argent Dawn, then a job I can offer.\n\nVenture to Stratholme and recover our surplus of holy water. Search the supply crates.", objectives = "Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid." }
WordHunterWoW_QuestEN[5244] = { title = "The Ruins of Kel'Theril", description = "The story behind Kel'Theril is one of a cursed race, bound to the place where they attempted an unfortunate ritual...\n\nThe highborne that you will find there once stole a sacred artifact, believing that they could siphon its power for themselves, becoming even more powerful. In their efforts, the relic shattered in a huge explosion, driving the pieces below the ice of the lake...\n\nSpeak with Jaron Stoneshaper if you'd like to learn more; he has recently visited the area and can tell you more.", objectives = "Speak with Jaron Stoneshaper in Starfall Village." }
WordHunterWoW_QuestEN[5245] = { title = "Troubled Spirits of Kel'Theril", description = "The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.\n\nIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.", objectives = "Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands." }
WordHunterWoW_QuestEN[5246] = { title = "Fragments of the Past", description = "I did not realize... Forgive my callous words, <class>.\n\nThe mistakes of my ancestors are not what I wish to dwell on, but if your request is truly genuine, then I will help you.\n\n<Aurora examines the fragments.>\n\nI believe this is the Crystal of Zin-Malor, an artifact that can contain and control strong arcane forces. It could have been used for good, but the evil intentions of those that stole it caused it to shatter.\n\nGo to the Temple of Zin-Malor in Azshara - I can only hope the book is still there.", objectives = "Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands." }
WordHunterWoW_QuestEN[5247] = { title = "Fragments of the Past", description = "I will be able to help you, if recreating the artifact is truly what you wish to do.\n\nTo seal the pieces back together, I will need items with strong magical qualities. An enchanted thorium bar and five crystal restore... You'll also need to collect some water from what might seem an unlikely place... Find the dire pool along Eldreth Row at Dire Maul in Feralas, and fill this vial.\n\nWhile you are gone, I will attempt to glean from these pages the knowledge I need to repair the damage done to the relic.", objectives = "Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands." }
WordHunterWoW_QuestEN[5248] = { title = "Tormented By the Past", description = "<name>, I weep for what has happened in the past. Like this crystal, the elves, as a race, have been shattered. I do not know if the pieces will ever again be reunited into one, but my sorrow has been eased by being able to help you with this one small task. \n\nWe must not forget the past, <name>...\n\nPlease take the Crystal of Zin-Malor back to Lake Kel'Theril. You must find a highborne spirit that realizes the error of what was done so long ago. Show the spirit that we have made things right again.", objectives = "Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you." }
WordHunterWoW_QuestEN[5249] = { title = "To Winterspring!", description = "In Winterspring, to the north of here, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore.\n\nWith all my work to do here in Felwood, I have not had the opportunity to travel to Winterspring. But there's no reason why you shouldn't!\n\nWhile you're there, look for Wynd Nightchaser. He spends most of his time in Starfall Village and he knows a lot about the area.", objectives = "Find Starfall Village in Winterspring and speak with Wynd Nightchaser." }
WordHunterWoW_QuestEN[5250] = { title = "Starfall", description = "In Winterspring, to the north of Felwood, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore.\n\nMy studies here keep me so busy that I have not had the opportunity to travel to Winterspring for some time. But there's no reason why you shouldn't travel there and study the ruins.\n\nWhile you're there, look for Wynd Nightchaser. He spends most of his time in Starfall and he knows a lot about the area.\n\nTell him that you are a student of mine...", objectives = "Find Starfall in Winterspring and speak with Wynd Nightchaser." }
WordHunterWoW_QuestEN[5251] = { title = "The Archivist", description = "Anything taken to an extreme is hazardous to our world, <name>. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?\n\nBlasphemers, one and all!\n\nOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded.", objectives = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive." }
WordHunterWoW_QuestEN[5252] = { title = "Remorseful Highborne", description = "The... the crystal...\n\nThe highborne here are clouded by their own misssery...\n\nI am sorrrrrowful, but I realize the errorrrr of what happened so long ago. Even though there is no waaaay to change the past, I am now at peacccce knowing that you have recovered the crystal of Zin-Malor...\n\nYouuu must return it...\n\nIt muuuussst be returrrned.", objectives = "Speak with Wynd Nightchaser in Starfall Village, and ask about the proper place for the Crystal of Zin-Malor." }
WordHunterWoW_QuestEN[5253] = { title = "The Crystal of Zin-Malor", description = "Quite impressive, <name>.\n\nThe crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded.\n\nSeek out Arch Druid Fandral Staghelm in Darnassus, and bring the crystal to him, <name>. It should be in the hands of those that will not abuse its power. From the looks of it, only a handful of the strongest magic users would be able to control such a power.", objectives = "Deliver the Crystal of Zin-Malor to Arch Druid Fandral Staghelm in Darnassus." }
WordHunterWoW_QuestEN[5261] = { title = "Eagan Peltskinner", description = "Eagan Peltskinner is looking for someone to hunt diseased wolves for him.  That's good news, because we're seeing a lot more diseased wolves in Northshire Valley lately.\n\nIf you're interested then speak with Eagan.  He's around the side of the abbey, to the left.", objectives = "Speak with Eagan Peltskinner." }
WordHunterWoW_QuestEN[5262] = { title = "The Truth Comes Crashing Down", description = "You try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation.\n\nThe Grand Crusader of the Scarlet Crusade a demon? And not just any demon but brother to Varimathras, arch lord of the Undercity?\n\nYou carefully stow the severed head of the dreadlord into your pack. Surely, none would believe the tale you would tell without proof.\n\nDuke Nicholas Zverenhoff must be told at once!", objectives = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[5263] = { title = "Above and Beyond", description = "You display a natural aptitude for destruction and you follow orders. It is rare to see the two coexist. I am beginning to think that you may make an excellent vehicle of divine justice.\n\n<Zverenhoff clasps his hands together in front of his face.>\n\nKel'Thuzad's errand boy rules over Stratholme. Prove to me that you are a champion - my champion. Destroy Baron Rivendare and return to me with his head.", objectives = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff." }
WordHunterWoW_QuestEN[5264] = { title = "Lord Maxwell Tyrosus", description = "I am about to bestow a great honor upon you, <name>.\n\nLord Maxwell wishes to reward you for your service to the Argent Dawn!\n\nIt has been years since Maxwell has granted audience to outsiders.", objectives = "Speak with Lord Maxwell Tyrosus. He is inside the church." }
WordHunterWoW_QuestEN[5265] = { title = "The Argent Hold", description = "Through the years the Argent Hold has remained locked. None have been worthy to reach inside and take from it the power of the Argent Dawn - until today.\n\nThe Argent Hold is now open to you, <name>.", objectives = "Open the Argent Hold and claim your reward." }
WordHunterWoW_QuestEN[5281] = { title = "The Restless Souls", description = "There are those that died tragically in the fall of Stratholme. Many took their own lives, opting to hurl themselves into the myriad flames of the smoldering city rather than become one of the Scourge.\n\nThey now walk the streets of Stratholme as restless spirits.\n\nWe must aid them, <name>!\n\nI have an associate named Egan who has been doing miraculous work with ghosts and souls. Seek him out. He walks the eastern Plaguelands, near Stratholme, testing his innovations.", objectives = "Find Egan. You only know that he was last seen around Stratholme." }
WordHunterWoW_QuestEN[5282] = { title = "The Restless Souls", description = "I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done. I am, however, no zealot. There are those, like the Scarlet Crusade, who would sooner destroy the innocent undead than lend them even an ounce of compassion.\n\nWhich brings me to this: My blaster. It will unchain the tortured souls from Stratholme.\n\nUse it on the ghosts that haunt the ransacked streets. Free their souls.", objectives = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!\nFree 15 Restless Souls and return to Egan." }
WordHunterWoW_QuestEN[5283] = { title = "The Art of the Armorsmith", description = "So ye made the smart decision.\n\nThere ain't no love lost betwixt me an old Ironus here. That good for nothing toy maker knows who the true craftsmen round here be.\n\nThe truly great wars are won with a good defense. When it be go time, no offense is gonna be helping ye out.\n\nRight, so let's get to work. All ye need to do is show me that ye've got some raw talent. After that, I'll yank whatever impurities be left in ye and mold ye into an armorsmith. Ye do know how to make ornate mithril, don't ye?Upon completion of this quest you will gain:", objectives = "To become an Armorsmith, you must make the following items and return them to Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate." }
WordHunterWoW_QuestEN[5284] = { title = "The Way of the Weaponsmith", description = "As a weaponsmith you'll find that more often than not, heroes and adventurers will be coming to you for gear. While the workload can be unbearable at times, the riches more than make up for the back strain and ash lung.\n\nOh yes, <name>, weaponsmiths are the ones with all the gold!\n\nIf you wish to join our ranks, you'll need to show me that you can make me a silver or two - I mean, show me that you've got what it takes to be the go to <guy/girl> when people need superior quality weapons. Get to work!Upon completion of this quest you will gain:", objectives = "To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces." }
WordHunterWoW_QuestEN[5301] = { title = "The Art of the Armorsmith", description = "Satisfaction. It is what I draw from the hammer and the anvil. To see a proud Horde warrior protected under my steel reminds me of what it is to be alive. It is an addiction that I dare never give up, <name>.\n\nI can not grant you this satisfaction, merely set you upon the path. As with all of life's endeavors, the path of the armorsmith is a journey.\n\nIf you wish to be one of the select few, you need only to ask and I shall train, but, a task you must first complete.Upon completion of this quest you will gain:", objectives = "To become an armorsmith, you must make the following items and return them to Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate." }
WordHunterWoW_QuestEN[5302] = { title = "The Way of the Weaponsmith", description = "One day, I will create a legendary hammer. A hammer fit for a Warchief!\n\nIt is my life's work, <name>. My passion. I recognize that you have the potential to be among us, one of us - a weaponsmith. I am the one that can help you harness that potential.\n\nA simple task is all that you must complete. Simple for one of your exceptional skill.Upon completion of this quest you will gain:", objectives = "To become a Weaponsmith, you must make the following items and return them to Borgosh: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces." }
WordHunterWoW_QuestEN[5305] = { title = "Sweet Serenity", description = "Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall reward you with the knowledge required to create an enchanted battlehammer!", objectives = "Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith." }
WordHunterWoW_QuestEN[5306] = { title = "Snakestone of the Shadow Huntress", description = "Don't let her beauty fool you, <class>. The shadow huntress, Vosh'gajin is deadly and deranged.\n\n<Kilram points to the scar on his face.>\n\nAye, she gave me that - a love tap, she called it.\n\nThe time for vengeance has finally come.\n\nYou can find Vosh'gajin in Blackrock Spire. Slay her and return to me with her snakestone. Do this and I will teach you the secret to crafting Dawn's Edge!", objectives = "Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram." }
WordHunterWoW_QuestEN[5307] = { title = "Corruption", description = "If I am short with you, it is for a reason. The plans for the creation of the great blade, Corruption, have been stolen by the Black Guard: Elite skeletal units of Baron Rivendare.\n\nYes, Baron Rivendare of Stratholme.\n\nThe Black Guard swordsmith now guards those plans with his... undeath.\n\nSlay him and return proof of this deed and I shall grant you the knowledge required to create a blazing rapier!", objectives = "Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane." }
WordHunterWoW_QuestEN[5321] = { title = "The Sleeper Has Awakened", description = "I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy...\n\n<yawn>\n\nWould you mind showing me the way? I understand that Maestra's Post is south of here, along the road in Ashenvale. It can be dangerous, so I hope you have some friends that will join us.\n\nLastly, I may fall asleep so if you ever need to wake me, please use my horn. You'll find it in the chest here.", objectives = "Escort Kerlonian Evershade to Liladris Moonriver at Maestra's Post in Ashenvale." }
WordHunterWoW_QuestEN[5341] = { title = "Barov Family Fortune", description = "Within the Scholomance lays the Barov family fortune. I, Alexi Barov, am one of the last two remaining heirs of the house Barov. My brother, Weldon, is the other.\n\nWeldon, the miserable coward, fled during the war and thus retained his worthless existence as a human.\n\nHe now searches for the deeds so that he may claim the fortune for his own. Recover the deeds before my brother does and I shall make you wealthy beyond your wildest dreams!", objectives = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task." }
WordHunterWoW_QuestEN[5342] = { title = "The Last Barov", description = "Naturally, with my brother still alive, there may be some contention as to the primary beneficiary of the family's fortune. This cannot be.\n\nA low down guttersnipe like you isn't above a little cold-blooded murder, I hope.\n\nIt's a simple task and one that I expect you will complete; that is, if you wish to claim your reward.\n\nWeldon sits under Alliance protection at Chillwind Camp, to the east. Slay him, return his head.\n\n<Alexi yawns.>\n\nHurry along now.", objectives = "Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.\nBe warned, Weldon will probably be well protected by Alliance scum." }
WordHunterWoW_QuestEN[5343] = { title = "Barov Family Fortune", description = "My dear brother Alexi. What a fool I was to spare his life. I looked into the face of the enemy, one of the undead, and let him live.\n\n<Weldon spits.>\n\nHe now searches for MY inheritance. This simply cannot happen.\n\nFind my family's deeds before that vile retch gets his boney hands upon them and I shall reward you with vast riches. They lay in the ruins of the Scholomance. Make haste!", objectives = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task." }
WordHunterWoW_QuestEN[5344] = { title = "The Last Barov", description = "With the deeds recovered, there is but one thing left to do. Alexi must be killed. With him dead, I need not ever worry about an unscrupulous gang of mercenaries seeking my head.\n\nIt's a simple task. Alexi hides under the protection of the Horde - at the Bulwark.\n\nNo, I do not expect you to just walk up and kill him, I want his head! How you get it... well, that part is up to you. That type of behavior is below one of my noble upbringing.", objectives = "Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.\nBe warned, Alexi will probably be well protected by Horde filth." }
WordHunterWoW_QuestEN[5361] = { title = "Family Tree", description = "My brother Nataka is stationed at Ghost Walker Post over in Desolace. I'd like to ask you... could you give this report to him for me? A year has passed since the last time I wrote, there has been unusual centaur activity since then and he should be informed.\n\nJourney to Stonetalon Mountain north of the Crossroads, and then head west into Charred Vale. From there, head south into Desolace; there you will find a road going south to Ghost Walker Post.", objectives = "Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace." }
WordHunterWoW_QuestEN[5381] = { title = "Hand of Iruxos", description = "The Burning Blade possesses the Demon Box. Within it lies the powerful Hand of Iruxos. The Burning Blade uses it to open demonic portals at Mannoroc Coven. We must stop the tide of demons entering our world, <name>!\n\nUse this demon pick on the red crystal in Thunder Axe Fortress to gain access to the Demon Box.", objectives = "Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village." }
WordHunterWoW_QuestEN[5382] = { title = "Doctor Theolen Krastinov, the Butcher", description = "Krastinov is responsible for the deaths of thousands. He must be punished, justice must be meted out.\n\nFind him and exact upon him the agony he has inflicted upon countless innocents. Once he is destroyed, burn our remains. Turn them to ashes, <name>.", objectives = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete." }
WordHunterWoW_QuestEN[5384] = { title = "Kirtonos the Herald", description = "This is it, <name>.\n\n<Eva points to the vial inside the bag.>\n\nThe blood of innocents. The purest blood, used to appease Krastinov's master.\n\nIt is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed.\n\nTake the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.\n\nShould you succeed, you will earn more than just our gratitude.", objectives = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.\nFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff." }
WordHunterWoW_QuestEN[5385] = { title = "The Remains of Trey Lightforge", description = "You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends.", objectives = "Return the Remains of Trey Lightforge to Jessir Moonbow in Felwood." }
WordHunterWoW_QuestEN[5386] = { title = "Catch of the Day", description = "The smell of cooked fish has long been missing here at Ghost Walker Post. The trolls at Shadowprey Village are the best at catching fish... but alas, with all the centaur activities I have little time to make a journey to the trolls. Hrm...\n\nDo me a favor and journey to Shadowprey Village. Talk to the local fisherman Jinar'Zillen and bring me back my favorite, Bloodbelly fish. The road south of here will take you west to the troll village.", objectives = "Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish." }
