WordHunterWoW_QuestEN[5513] = { title = "Mantles of the Dawn", description = "Your service to the Argent Dawn is to be commended, <name>.  You are truly revered amongst us.  I have been authorized to make available for you to purchase one of the Dawn's most valued items - our magic resistance mantles.\n\nApplication of a mantle to your existing shoulder piece will enhance your resistance to the powers of magic in one of five potential ways.  As a sign of continued dedication to our cause, I ask for no less than ten of our valor tokens in exchange for access to these mantles.", objectives = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands." }
WordHunterWoW_QuestEN[5514] = { title = "Mold Rhymes With...", description = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an apothecary, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!", objectives = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan." }
WordHunterWoW_QuestEN[5515] = { title = "Krastinov's Bag of Horrors", description = "A great weight has been lifted from our hearts, <name>, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.\n\nBefore you may face Kirtonos, however, you must first secure a method in which to summon him.\n\nIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.\n\nFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.", objectives = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff." }
WordHunterWoW_QuestEN[5517] = { title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> <name> - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.You will receive:", objectives = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands." }
WordHunterWoW_QuestEN[5518] = { title = "The Gordok Ogre Suit", description = "If you're going to fight the king of this dump - and I think that's what you're bound to do - then you're going to need to get by Captain Kromcrush.  Now, you can get by him by killing him, sure.  You might actually want to leave him alive.\n\nHow, you ask?  Since I've been here, I think I know how to make an ogre suit that will last just long enough to fool these bozos.  The only problem is stability - ten minutes tops.  Bring me what I need, and I'll make you one.  I'm not going anywhere...", objectives = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul." }
WordHunterWoW_QuestEN[5519] = { title = "The Gordok Ogre Suit", description = "", objectives = "" }
WordHunterWoW_QuestEN[5521] = { title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> <name> - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.You will receive:", objectives = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands." }
WordHunterWoW_QuestEN[5522] = { title = "Leonid Barthalomew", description = "I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.\n\nLeonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.\n\nThat hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded.", objectives = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[5524] = { title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> <name> - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.You will receive:", objectives = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5525] = { title = "Free Knot!", description = "", objectives = "" }
WordHunterWoW_QuestEN[5526] = { title = "Shards of the Felvine", description = "Your knowledge of Eldre'Thalas - Dire Maul - in Feralas will now come into play, <name>.  In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion.  Go there with all due haste and brave whatever challenges await you.\n\nThe Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin.  When he falls, capture whatever essence of the Felvine you can.  Seal it in the Reliquary, and bring it to me.\n\nGood luck, and Cenarion's speed.", objectives = "Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade." }
WordHunterWoW_QuestEN[5527] = { title = "A Reliquary of Purity", description = "The first step is to find a container capable of holding an extremely corruptible substance without the handler suffering ill effects.  There is only one sort device I am aware of that could possibly contain something as vile as the Felvine: a Reliquary of Purity.\n\nDeep in the wasteland of Silithus is the remnants of the night elf village known as Southwind.  I know one was there many, many years ago.  If we are to succeed, I need you to scour those ruins in the hopes of reclaiming it.", objectives = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade." }
WordHunterWoW_QuestEN[5528] = { title = "The Gordok Taste Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[5529] = { title = "Plagued Hatchlings", description = "The Argent Dawn recently learned that the Scourge are creating their own plagued dragonflight!  We must stop them -- if the Scourge gain a force of dragons they'll sweep across Azeroth unchecked!\n\nTheir necromancers are breeding plagued dragons at the Scholomance, in the middle of Darrowmere Lake.\n\nGo to the Scholomance and kill as many hatchlings as you can... before they get any bigger!", objectives = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel." }
WordHunterWoW_QuestEN[5531] = { title = "Betina Bigglezink", description = "The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.\n\nNow, it is time we ended their research.\n\nTake the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow.", objectives = "Bring the Frozen Eggs to Betina Bigglezink." }
WordHunterWoW_QuestEN[5533] = { title = "Scholomance", description = "On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil.  Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nAlchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your worth to me, and now I entrust this task to you.  Speak with him on this matter.", objectives = "Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands." }
WordHunterWoW_QuestEN[5534] = { title = "Kim'jael's \"Missing\" Equipment", description = "What?! What?!\n\nThat wasn't good enough for you? You know how expensive those explosives are? They sell for... oh, nevermind. Fine, you want to make some real money? Cause that's how business is done: you prove you're a valuable employee and then you're rewarded adequately after you stick it out some.\n\nIf you're a \"valuable\" employee, then hit the Ruins of Eldarath and find me some rune that them Blood elves were lookin' for. The naga apparently have it in their possession.", objectives = "Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara." }
WordHunterWoW_QuestEN[5535] = { title = "Spiritual Unrest", description = "Long ago, the Highborne were some of the most powerful students of the arcane the night elves ever produced. The corruption that comes along with such studies caused much harm to night elf society and greatly affected all of Azeroth... as I'm sure you well know.\n\nI promised the Sentinels that I would release the spirits from their mortal bonds as I find them. If you would do the same, then I am sure I can reward you some.\n\nThe spirits haunt the Shadowsong Shrine to the northeast of here.", objectives = "Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara." }
WordHunterWoW_QuestEN[5536] = { title = "A Land Filled with Hatred", description = "The satyr, a disfigured, evil aspect of the night elves, now infect the sacred lands once traveled by Cenarius. I cannot speak for the night elves when it comes to all the atrocities those demonic creatures have committed, but I have sworn an oath to the Earthmother to aid the elves in ridding the land of such a nuisance.\n\nI am sure you would prove yourself if you aided me in purging them.\n\nNortheast of here, you can find the Haldarr clan. Return to me after you've tested yourself against their power.", objectives = "Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale." }
WordHunterWoW_QuestEN[5537] = { title = "Skeletal Fragments", description = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, <name>.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.", objectives = "Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands." }
WordHunterWoW_QuestEN[5538] = { title = "Mold Rhymes With...", description = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an alchemist, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!", objectives = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan." }
WordHunterWoW_QuestEN[5541] = { title = "Ammo for Rumbleshot", description = "Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he's always needing fresh ammunition.\n\nBut... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot's ammo behind!\n\n<name>, can you get that ammo and take it to Rumbleshot?  He's been waiting on it and I'm sure he's running low.", objectives = "Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh." }
WordHunterWoW_QuestEN[5542] = { title = "Demon Dogs", description = "If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'\n\nYou can start with the Plaguehounds and their runts.\n\nI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed.", objectives = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete." }
WordHunterWoW_QuestEN[5543] = { title = "Blood Tinged Skies", description = "Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.\n\nEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats.", objectives = "Slay 30 Plaguebats and return to Tirion Fordring." }
WordHunterWoW_QuestEN[5544] = { title = "Carrion Grubbage", description = "My food supplies are running low, <race>. I am ashamed to admit that I might not have enough food to share with you.\n\nCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!", objectives = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat." }
WordHunterWoW_QuestEN[5545] = { title = "A Bundle of Trouble", description = "I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped.\n\nI've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.", objectives = "Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp." }
WordHunterWoW_QuestEN[5561] = { title = "Kodo Roundup", description = "Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership.\n\nTake the kombobulator and use it on any ancient or aged kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me.", objectives = "Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp." }
WordHunterWoW_QuestEN[5581] = { title = "Portals of the Legion", description = "Here it is - the Hand of Iruxos.\n\nGot it from one of the Burning Blade leaders myself.\n\nYou must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do.\n\nWith the demon threat increasing we must close these portals to stem the tide of demons to this world.", objectives = "Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village." }
WordHunterWoW_QuestEN[5582] = { title = "Healthy Dragon Scale", description = "This is a scale shed from a plagued dragon hatchling.  But unlike the other pocked, oozing scales on the infant beast, this rare scale is healthy and unmarred.\n\nBetina Bigglezink will want a sample of this to study.", objectives = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands." }
WordHunterWoW_QuestEN[5601] = { title = "Sister Pamela", description = "I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire.\n\nDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.\n\nPlease, find her for me!", objectives = "Find Pamela Redpath in Darrowshire." }
WordHunterWoW_QuestEN[5621] = { title = "Garments of the Moon", description = "I need your help, <name>. I am needed here to train the other students, but you, you can help one of our injured Sentinels just south of Dolanaar. She was hurt patrolling the town and could use our aid. Her name is Shaya.\n\nWhen you find her, heal her wounds, and then fortify her body with your spells. This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune.You will receive:", objectives = "Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar." }
WordHunterWoW_QuestEN[5622] = { title = "In Favor of Elune", description = "<name>, you must travel to Dolanaar when your business here in Shadowglen is done. There, you will find Laurna Morninglight. She will instruct you further in the ways of Elune, and it is with her that you will earn your first garments denoting your station as a <priest/priestess> of Elune.\n\nTake care, and may you be protected in your journeys.Upon completion of this quest you will gain:", objectives = "Speak to Laurna Morninglight in Teldrassil." }
WordHunterWoW_QuestEN[5623] = { title = "In Favor of the Light", description = "Hello again, young <priest/priestess>. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Josetta in Elwynn Forest." }
WordHunterWoW_QuestEN[5624] = { title = "Garments of the Light", description = "Normally I put forth a small challenge to followers of the Light to test their skill. I want to see if they are worthy of wearing their first robes--a sign that the church outwardly approves of the <priest/priestess> and supports <him/her>.\n\nBut this situation is a bit different. One of Goldshire's citizens saw an injured guard near the lake to the east of here. His name is Roberts. Find him, heal him, fortify his body and return here. If you can do that for me, then I will consider your test complete.You will receive:", objectives = "Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire." }
WordHunterWoW_QuestEN[5625] = { title = "Garments of the Light", description = "It's usually about this time that one of your power is tested to see if they're worthy of wearing robes denoting their place in the church. But to be honest, I got more pressing matters to look into. Citizen of Kharanos' just came in here and told me 'bout a hurt mountaineer just outside town to the south--name's Dolf.\n\nYou heal Dolf and give him Fortitude, and I'll consider you done with proving yourself. How's that sound?You will receive:", objectives = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos." }
WordHunterWoW_QuestEN[5626] = { title = "In Favor of the Light", description = "Hey! <name>! Got a minute?!\n\nYa been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a <priest/priestess>.\n\nNow get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.Upon completion of this quest you will gain:", objectives = "Speak to Maxan Anvol in Dun Morogh." }
WordHunterWoW_QuestEN[5627] = { title = "Stars of Elune", description = "", objectives = "" }
WordHunterWoW_QuestEN[5628] = { title = "Returning Home", description = "Ah, yes, hello, <name>? I'm glad you stopped to talk for a moment. You are a far way from home at such a young age--I admire such ambition. I wish when I was younger I could have mustered the courage to travel the world.\n\nThere was a priestess of your order here looking for you not too long ago. She said it was very urgent you returned to the Temple of the Moon in Darnassus and speak to Priestess Alathea--it had something to do with your training. I wouldn't dally too long if you can help it.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5629] = { title = "Returning Home", description = "Hello again, <name>. I know you've been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you've caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5630] = { title = "Returning Home", description = "Hello there, <laddy/lassy>. Good to see you travelin' far and wide to distant lands. No offense meant, but a lot o' your kind don't take well to these cold climates usually. Glad to see you're made of tougher stuff.\n\nNot too long ago one of your priestesses was in here lookin' for you--said somethin' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5631] = { title = "Returning Home", description = "A priestess recently visited our halls seeking you out, young <race>. She said that she was on a mission to find you and that you should return to the Temple of the Moon in Darnassus as soon as possible. When you arrive, seek out a Priestess Alathea--she will tell you more.\n\nThe Light be with you, <name>.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5632] = { title = "Returning Home", description = "Oh, yes, of course. Hello, <name>. A messenger from our order was here not too long ago looking for you. She mentioned something important happening back in Darnassus and that you should return to the Temple of the Moon as soon as you can. When you arrive, speak to Priestess Alathea. I believe it has something to do with your progressing so well in our ways.\n\nAgain, return to Darnassus when you can.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5633] = { title = "Returning Home", description = "Greetings, <laddy/lass>. Good to see you here in our great halls. A blessing be on you and your kind.\n\nWhile you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I'm sorry I can't tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5634] = { title = "Desperate Prayer", description = "", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5635] = { title = "Desperate Prayer", description = "You've caught the attention of our superiors, <name>. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.Upon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5636] = { title = "Desperate Prayer", description = "Elune bless you, good <race>. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.Upon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5637] = { title = "Desperate Prayer", description = "Time's come for you to head to Stormwind, <name>. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can.Upon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5638] = { title = "Desperate Prayer", description = "Just a short time ago, one of your priests was here looking for you, <race>. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good <race>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5639] = { title = "Desperate Prayer", description = "You're needed in Stormwind, <name>. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, <name>.", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5641] = { title = "A Lack of Fear", description = "", objectives = "Speak to High Priest Rohan in Ironforge." }
WordHunterWoW_QuestEN[5642] = { title = "Shadowguard", description = "Something important is up in Orgrimmar, <name>.\n\nThe normal messengers that come through here looking for troll priests usually are very casual. This time, they seemed to be in much more a hurry. Don't dally too long in Thunder Bluff. I'd return to the Valley of Spirits as soon as possible.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar." }
WordHunterWoW_QuestEN[5643] = { title = "Shadowguard", description = "Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.Upon completion of this quest you will gain:", objectives = "Speak to Ur'kyo in Orgrimmar." }
WordHunterWoW_QuestEN[5644] = { title = "Devouring Plague", description = "Ah, a wonderful day for you, <name>. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy.\n\nI will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days.\n\nGo back to Aelthalyste in the Undercity, <name>. She will be awaiting you in the War Quarter.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5645] = { title = "A Lack of Fear", description = "<name>, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.Upon completion of this quest you will gain:", objectives = "Speak to High Priest Rohan in Ironforge." }
WordHunterWoW_QuestEN[5646] = { title = "Devouring Plague", description = "Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe.\n\nYou return to the Undercity, <name>. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5647] = { title = "A Lack of Fear", description = "Your race is so very strong, <name>. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to not only finding your true origins, but find great confidence that you are on the right path in so many things. That feeling must make you feel so triumphant.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priest Rohan in the Mystic Ward. I would not keep him waiting. May Elune guide your travels.You will also receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priest Rohan in Ironforge." }
WordHunterWoW_QuestEN[5648] = { title = "Garments of Spirituality", description = "You be ready for your first test, <name>. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops. She not doin' too well, an' she benefit much if one of our kind could help her. Find her--her name be Kor'ja--heal her wounds, an' give her the blessin' of our ancestors.\n\nYou do this, an' me thinks that be sufficient proof that you ready to move on in our ways.You will receive:", objectives = "Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill." }
WordHunterWoW_QuestEN[5649] = { title = "In Favor of Spirituality", description = "Aye, mon. Our kind have joined the Horde because they be good for us. They loyal, and they teach us much 'bout tings like honor. But our old ways die hard. The orcs may not approve of all our traditions, but that not mean we can't continue to practice some them in secret.\n\nYou know this, an' that's why I send you to Tai'jin in Razor Hill. She teach you more 'bout our history. She teach you the ways of our tribe. Go to her when you be ready.Upon completion of this quest you will gain:", objectives = "Speak to Tai'jin in Durotar." }
WordHunterWoW_QuestEN[5650] = { title = "Garments of Darkness", description = "Our power comes from darkness and shadow, <name>, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts. This is wise. But before you can know the dark, you must also know the light. And for this, I have a test for you.\n\nNorth of the cemetery is a wounded Deathguard--Deathguard Kel. He has protected us from gnolls for some time, and needs healing. But, you must also fortify his body before he can return to duty. Do both with your spells, and then return to me.You will receive:", objectives = "Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill." }
WordHunterWoW_QuestEN[5651] = { title = "In Favor of Darkness", description = "There are many lessons that the Forsaken have learned through experience--things that some races can only begin to fathom. And although our path lies in darkness, you will find that a great many things rely on both the light and the dark. Your lessons shall teach you to use both... and with discretion. But heed my words: never forget we were forged in corruption and left to rot like so much carrion. The Darkness is our home.\n\nSeek out Dark Cleric Beryl in Brill when you're ready to learn more.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Dark Cleric Beryl in Tirisfal Glades." }
WordHunterWoW_QuestEN[5652] = { title = "Hex of Weakness", description = "", objectives = "Speak to Ur'kyo in Orgrimmar." }
WordHunterWoW_QuestEN[5654] = { title = "Hex of Weakness", description = "It be time for you to meet with Ur'kyo, <name>. He be in the Valley of Spirits in the orc city. Go there and speak to him. It is time you learn more of the old ways of our kind. It time you be brought into the circle and made a true priest of our tribe.Upon completion of this quest you will gain:", objectives = "Speak to Ur'kyo in Orgrimmar." }
WordHunterWoW_QuestEN[5655] = { title = "Hex of Weakness", description = "I sent here to make sure that you not wander too far from home, <name>. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You go to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar." }
WordHunterWoW_QuestEN[5656] = { title = "Hex of Weakness", description = "It always warms my undying heart to see priests from all cultures wander the world. To know that power exists that is not arcane and well within our grasp. That's why it is my honor to direct you home, <name>.\n\nUr'kyo, your great priest in Orgrimmar, has asked for your presence. You can find him in the Valley of Spirits.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar." }
WordHunterWoW_QuestEN[5657] = { title = "Hex of Weakness", description = "Home. Return home, young <race>.\n\nYour spiritual leader Ur'kyo begs you to return to him and speak about the path you travel.\n\nGo to the Valley of Spirits in the great Horde city of Orgrimmar. You will find him there.You will receive:", objectives = "Speak to Ur'kyo in Orgrimmar." }
WordHunterWoW_QuestEN[5658] = { title = "Touch of Weakness", description = "", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5660] = { title = "Touch of Weakness", description = "You be far from home, <class>. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5661] = { title = "Touch of Weakness", description = "You be far from home out here in the Bloodhoof Village, <name>. I be sent here to find priests of my own tribe to send back to speak to our leaders, but that not mean I cannot help you too.\n\nI hear word that your head priestess spirit want all Forsaken to come to her--there are things you must learn.\n\nGo to meet Aelthalyste in the War Quarter in that city of yours.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5662] = { title = "Touch of Weakness", description = "My respect to you and your kind, <name>. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron.\n\nYou should return to her if you're to learn those abilities that set you apart from other faiths.\n\nGo to the War Quarter in the Undercity and find your mistress there.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5663] = { title = "Touch of Weakness", description = "Aelthalyste sent word out to all her priests. We're to direct the younger of our order to the Undercity for more training. If you truly count yourself among our faithful, then you should return there also.\n\nYou can find Aelthalyste in the War Quarter deep in the Undercity.Upon completion of this quest you will gain:", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5672] = { title = "Elune's Grace", description = "", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5673] = { title = "Elune's Grace", description = "You know you have access to any of our trainers at any time, <name>, but there are some things that we cannot pass on to you. One of those things are the teachings of your goddess Elune. She gives special abilities to her faithful, and if I'm not mistaken, it is time for you to return home to your Temple of the Moon to be tested.\n\nReturn there when you can and speak to Priestess Alathea.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5674] = { title = "Elune's Grace", description = "A wonderful day has come, <name>. You've reached the age in which our <priests/priestesses> are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5675] = { title = "Elune's Grace", description = "Time's a wastin', <lad/lass>. It's time for you to return home to Darnassus. Priestess Alathea's sent word here that you're to return there for training. Seems they feel you're ready to be tested much like those who serve the Light. You should head out whenever you can. Alathea's message said that she'd be waitin' for you in the Temple of the Moon. Good luck.Upon completion of this quest you will gain:", objectives = "Speak to Priestess Alathea in Darnassus." }
WordHunterWoW_QuestEN[5676] = { title = "Arcane Feedback", description = "", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5677] = { title = "Arcane Feedback", description = "As much as I'd like to show you our own special teachings of the Light, it is not our place. Your place is back in Stormwind with your own kind, <name>... for now. Believe me, I mean no offense. When you return to High Priestess Laurena in the Cathedral of Light you'll understand what I'm talking about--the time has come for your race to prepare you for the future; to separate yourself from others that follow a similar path.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to High Priestess Laurena in Stormwind." }
WordHunterWoW_QuestEN[5679] = { title = "Devouring Plague", description = "", objectives = "Speak to Aelthalyste in the Undercity." }
WordHunterWoW_QuestEN[5680] = { title = "Shadowguard", description = "", objectives = "Speak to Ur'kyo in Ogrimmar." }
WordHunterWoW_QuestEN[5713] = { title = "One Shot. One Kill.", description = "I was traveling to Lor'danel with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready.\n\nI would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can.\n\nShould we survive, I will be able to deliver my message to Lor'danel, while you speak with Onaeya at Maestra's Post to inform her of this incident.", objectives = "Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale." }
WordHunterWoW_QuestEN[5721] = { title = "The Battle of Darrowshire", description = "Now, <name>, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.", objectives = "Place the Relic Bundle at the Darrowshire town square.\nPrevent Davil Lightfire's death until the death of Horgus.\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\nDefeat Redpath the Corrupted.\nSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home." }
WordHunterWoW_QuestEN[5722] = { title = "Searching for the Lost Satchel", description = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.", objectives = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest." }
WordHunterWoW_QuestEN[5723] = { title = "Testing an Enemy's Strength", description = "Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.\n\nShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.", objectives = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff." }
WordHunterWoW_QuestEN[5724] = { title = "Returning the Lost Satchel", description = "You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs.\n\nRemoving the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff.", objectives = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff." }
WordHunterWoW_QuestEN[5725] = { title = "The Power to Destroy...", description = "Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.\n\nA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for her.Upon completion of this quest you will gain:", objectives = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity." }
WordHunterWoW_QuestEN[5726] = { title = "Hidden Enemies", description = "One thing I will not tolerate are traitors in our midst, <name>. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.", objectives = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar." }
WordHunterWoW_QuestEN[5727] = { title = "Hidden Enemies", description = "Now let us see if this insignia you found is worth the effort.\n\nThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.\n\nTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.", objectives = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar." }
WordHunterWoW_QuestEN[5728] = { title = "Hidden Enemies", description = "Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.\n\nReturn to the Cleft of Shadow and enter Ragefire Chasm, <name>. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his <brothers/sisters> in arms.", objectives = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar." }
WordHunterWoW_QuestEN[5729] = { title = "Hidden Enemies", description = "I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.\n\nReturn to the Cleft and speak to him again, but do not be too overt.", objectives = "Speak to Neeru Fireblade in Orgrimmar." }
WordHunterWoW_QuestEN[5730] = { title = "Hidden Enemies", description = "You are one of my lieutenants! Prepare yourself, <class>. I will call upon you soon.\n\nMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.", objectives = "Speak to Thrall in Orgrimmar and tell him what you've learned." }
WordHunterWoW_QuestEN[5741] = { title = "Sceptre of Light", description = "The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power.\n\nTo that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers.", objectives = "Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor." }
WordHunterWoW_QuestEN[5742] = { title = "Redemption", description = "You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself.", objectives = "Listen to what Tirion Fordring has to say." }
WordHunterWoW_QuestEN[5761] = { title = "Slaying the Beast", description = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.\n\nIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.\n\nKill him, and his heart will appease Thrall, of this I'm sure.", objectives = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar." }
WordHunterWoW_QuestEN[5762] = { title = "Hemet Nesingwary", description = "I have a package for a new customer of mine, a dwarf named Hemet Nesingwary Jr..  The package took weeks to arrive, and Hemet's long gone by now.  He said he was going to Stranglethorn to take his father's place and hunt the beasts there, but he left me some money to send his delivery when I could.  \n\nJunior's a rich dwarf and it's a good idea to keep up relations with the rich ones, yeah?  So... you want to deliver the package for me?\n\nI heard he has a camp in Stranglethorn, north of Grom'gol.", objectives = "Take Kravel's Crate to Hemet Nesingwary in Stranglethorn." }
WordHunterWoW_QuestEN[5763] = { title = "Hunting in Stranglethorn", description = "Long ago, a dwarf came to this land.  His name was Hemet and he wished to hunt great beasts.  His skills with the rifle were uncanny, and we spent many days hunting together.  Even the enmity between our peoples was forgotten.\n\nWhen he left for Stranglethorn, I vowed to one day welcome him back.  Now he has gone on to hunt in lands unknown, but his son has taken his place.\n\nTake this kodo horn as a gift to Hemet Jr..  You will find him in Stranglethorn, north of the Grom'gol Base camp.", objectives = "Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn." }
WordHunterWoW_QuestEN[5781] = { title = "Of Forgotten Memories", description = "To help Taelan regain what he has lost, you must gather items from his past.\n\nThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.\n\nAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.\n\nYou must venture to the Undercroft and recover Taelan's hammer.", objectives = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective." }
WordHunterWoW_QuestEN[5801] = { title = "Fire Plume Forged", description = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.\n\nTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.\n\nThat's it on my end.  To finish your key, you'll need to talk to Arbington again.", objectives = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\nBring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands." }
WordHunterWoW_QuestEN[5802] = { title = "Fire Plume Forged", description = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.\n\nTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.\n\nThat's it on my end.  To finish your key, you'll need to talk to Dithers again.", objectives = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\nBring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5803] = { title = "Araj's Scarab", description = "Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.\n\nMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!\n\nThe Key to Scholomance awaits, <name>!", objectives = "Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands." }
WordHunterWoW_QuestEN[5804] = { title = "Araj's Scarab", description = "Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.\n\nMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!\n\nThe Key to Scholomance awaits, <name>!", objectives = "Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands." }
WordHunterWoW_QuestEN[5805] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Merissa Stilwell in Goldshire.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!\n", objectives = "Bring the Northshire Gift Voucher to Merissa Stilwell." }
WordHunterWoW_QuestEN[5821] = { title = "Bodyguard for Hire", description = "Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop. It's not good for business to be dead!\n\nI'll tell you what {class}, if you protect us past the Kolkar village we'll make it worth your while.\n\nIt's just a short distance, all you need to do is keep the caravan intact and you can pick up your reward from Smeed Scrabblescrew - he is down the road a bit. We do a little business together.", objectives = "Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward." }
WordHunterWoW_QuestEN[5841] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Yori Crackhelm in Kharanos.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Coldridge Valley Gift Voucher to Yori Crackhelm." }
WordHunterWoW_QuestEN[5842] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Orenthil Whisperwind in Dolanaar.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Shadowglen Gift Voucher to Orenthil Whisperwind." }
WordHunterWoW_QuestEN[5843] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Magga in Razor Hill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Valley of Trials Gift Voucher to Magga." }
WordHunterWoW_QuestEN[5844] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Vorn Skyseer in Bloodhoof Village.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Camp Narache Gift Voucher to Vorn Skyseer." }
WordHunterWoW_QuestEN[5845] = { title = "Of Lost Honor", description = "The Order of the Silver Hand was utterly decimated when Uther was slain.\n\nThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.\n\nWere any of the Order left alive, he thought - and did it matter?\n\nIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.\n\nYou must travel to Northdale and recover that symbol of lost honor.", objectives = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective." }
WordHunterWoW_QuestEN[5846] = { title = "Of Love and Family", description = "When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.\n\nIf this painting still exists, you must find it.\n\nTravel to the ruined island of Caer Darrow and see if the painting or the artist remain.", objectives = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting." }
WordHunterWoW_QuestEN[5847] = { title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Claire Willower in Brill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", objectives = "Bring the Deathknell Gift Voucher to Claire Willower in Deathknell." }
WordHunterWoW_QuestEN[5848] = { title = "Of Love and Family", description = "The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.\n\nAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.\n\nTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'\n\nMay the Light guide your actions.", objectives = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\nReturn the painting to Tirion Fordring." }
WordHunterWoW_QuestEN[5861] = { title = "Find Myranda", description = "<name>, you have done all that I have asked thus far. Only one step remains in your quest of redemption.\n\nYou must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight.\n\nThere is only one way in which to deliver my message and that is through a guise of deception.\n\nTo the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you.", objectives = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift." }
WordHunterWoW_QuestEN[5862] = { title = "Scarlet Subterfuge", description = "I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations.\n\nShould you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time.\n\nSpeak to me again when you are ready.", objectives = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.\nHearthglen is to the north, Taelan should be inside of Mardenholde Keep." }
WordHunterWoW_QuestEN[5863] = { title = "The Dunemaul Compound", description = "Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound. Several smaller bands are currently wandering the desert, some of which have invaded the old troll ruins.\n\nThe Dunemaul Compound must be destroyed! We cannot allow these ogres to build up a force.\n\nThe leader of this band is named Gor'marok the Ravager; I believe that putting an end to his leadership will be the beginning of the end for the ogres.", objectives = "Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager." }
WordHunterWoW_QuestEN[5881] = { title = "Calling in the Reserves", description = "The Horde does well keeping our troops fresh... since the Great War we have been prosperous here in Kalimdor.\n\nI need you to do me a favor, I have a lad by the name of Grish Longrunner protecting the Great Lift in the southern barrens. Give him this letter; the letter will let him know that I have a reserve warrior coming to relieve him of duty so that he can visit his family. He requested this sometime ago and he would be happy to hear the news.", objectives = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens." }
WordHunterWoW_QuestEN[5882] = { title = "Salve via Hunting", description = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5883] = { title = "Salve via Mining", description = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5884] = { title = "Salve via Gathering", description = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", objectives = "" }
WordHunterWoW_QuestEN[5885] = { title = "Salve via Skinning", description = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", objectives = "" }
WordHunterWoW_QuestEN[5886] = { title = "Salve via Disenchanting", description = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser eternal essences will work.\n\nI just need a single lesser eternal essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", objectives = "" }
WordHunterWoW_QuestEN[5887] = { title = "Salve via Hunting", description = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5888] = { title = "Salve via Mining", description = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", objectives = "" }
WordHunterWoW_QuestEN[5889] = { title = "Salve via Gathering", description = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", objectives = "" }
