WordHunterWoW_QuestEN[7425] = { title = "Staghelm's Mojo Jamboree", description = "", objectives = "" }
WordHunterWoW_QuestEN[7426] = { title = "One Man's Love", description = "", objectives = "" }
WordHunterWoW_QuestEN[7427] = { title = "Wanted: MORE DWARVES!", description = "", objectives = "" }
WordHunterWoW_QuestEN[7428] = { title = "Wanted: MORE ORCS!", description = "", objectives = "" }
WordHunterWoW_QuestEN[7429] = { title = "Free Knot!", description = "", objectives = "" }
WordHunterWoW_QuestEN[7441] = { title = "Pusillin and the Elder Azj'Tordin", description = "I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.\n\nI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.\n\nFind the imp, Pusillin, and recover my book.\n\nSearch the Warpwood Quarter of Dire Maul for Pusillin.", objectives = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations." }
WordHunterWoW_QuestEN[7461] = { title = "The Madness Within", description = "Have you heard enough? Are you a <man/woman> of action?\n\nThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.", objectives = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest." }
WordHunterWoW_QuestEN[7462] = { title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!" }
WordHunterWoW_QuestEN[7463] = { title = "Arcane Refreshment", description = "A <race> mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years!\n\nI have something that will quench your thirst, but first you must do a task for me.\n\n<Lydros snickers.>\n\nThere is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued!\n\nVenture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.Upon completion of this quest you will gain:", objectives = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence." }
WordHunterWoW_QuestEN[7481] = { title = "Elven Legends", description = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", objectives = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find." }
WordHunterWoW_QuestEN[7482] = { title = "Elven Legends", description = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", objectives = "Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find." }
WordHunterWoW_QuestEN[7483] = { title = "Libram of Rapidity", description = "Master Winthalus lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...\n\nRegardless, if you are interested, you will need to present the Libram along with some basic reagents.\n\nHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!\n\n<Lydros shrugs.>", objectives = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity." }
WordHunterWoW_QuestEN[7484] = { title = "Libram of Focus", description = "This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old.\n\nThose among you who are more magically inclined might find this item interesting.\n\nThe Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession.\n\nBring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.", objectives = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus." }
WordHunterWoW_QuestEN[7485] = { title = "Libram of Protection", description = "He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.\n\nBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.\n\nOh, and check the north wing.", objectives = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection." }
WordHunterWoW_QuestEN[7486] = { title = "A Hero's Reward", description = "<name>, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.\n\nGo, <name>.  Claim your reward.", objectives = "Claim your reward from Hydraxis' Coffer." }
WordHunterWoW_QuestEN[7488] = { title = "Lethtendris's Web", description = "The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!\n\nStop her, <name>.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...", objectives = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas." }
WordHunterWoW_QuestEN[7489] = { title = "Lethtendris's Web", description = "The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies.\n\nLethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.", objectives = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas." }
WordHunterWoW_QuestEN[7490] = { title = "Victory for the Horde", description = "You have accomplished the impossible.\n\nThe brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Warchief's advisor Eitrigg.", objectives = "Take the Head of Onyxia to Thrall in Orgrimmar." }
WordHunterWoW_QuestEN[7491] = { title = "For All To See", description = "Overlord Natoj awaits your arrival in the Valley of Strength.\n\n<Eitrigg salutes you.>\n\nDo not keep the Horde waiting!", objectives = "Seek out Overlord Runthak in the Valley of Strength." }
WordHunterWoW_QuestEN[7492] = { title = "Camp Mojache", description = "Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.\n\nServe the Horde, <name>.  Go to Camp Mojache in Feralas and speak with Talo.", objectives = "Speak with Talo Thornhoof at Camp Mojache in Feralas." }
WordHunterWoW_QuestEN[7493] = { title = "The Journey Has Just Begun", description = "", objectives = "" }
WordHunterWoW_QuestEN[7494] = { title = "Feathermoon Stronghold", description = "<name>!  Your aid is needed in Feralas!\n\nAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.\n\nLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.\n\nServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.", objectives = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas." }
WordHunterWoW_QuestEN[7495] = { title = "Victory for the Alliance", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Grand Admiral in honor of the King.", objectives = "Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind." }
WordHunterWoW_QuestEN[7496] = { title = "Celebrating Good Times", description = "Seek out Major Mattingly in the Valley of Heroes, {name}. He will be expecting you...", objectives = "Seek out Major Mattingly in the Valley of Heroes." }
WordHunterWoW_QuestEN[7497] = { title = "The Journey Has Just Begun", description = "", objectives = "" }
WordHunterWoW_QuestEN[7498] = { title = "Garona: A Study on Stealth and Treachery", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7499] = { title = "Codex of Defense", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7500] = { title = "The Arcanist's Cookbook", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7501] = { title = "The Light and How To Swing It", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7502] = { title = "Harnessing Shadows", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7503] = { title = "The Greatest Race of Hunters", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7504] = { title = "Holy Bologna: What the Light Won't Tell You", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7505] = { title = "Frost Shock and You", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7506] = { title = "The Emerald Dream...", description = "The tome carries the mark of the Athenaeum.", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7507] = { title = "Foror's Compendium", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return Foror's Compendium of Dragon Slaying to the Athenaeum." }
WordHunterWoW_QuestEN[7508] = { title = "The Forging of Quel'Serrar", description = "If you wish to take on this task, present Lydros with the dull blade.", objectives = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros." }
WordHunterWoW_QuestEN[7509] = { title = "The Forging of Quel'Serrar", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.You will receive:", objectives = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\nDo this and Quel'Serrar will be yours." }
WordHunterWoW_QuestEN[7541] = { title = "Service to the Horde", description = "", objectives = "" }
WordHunterWoW_QuestEN[7562] = { title = "Mor'zul Bloodbringer", description = "<name>, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.\n\nThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes.\n\nGo, <name>.  This quest will be perilous, but a Warlock of your stature does not shy from danger!Upon completion of this quest you will gain:", objectives = "Speak with Mor'zul Bloodbringer in the Burning Steppes." }
WordHunterWoW_QuestEN[7563] = { title = "Rage of Blood", description = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.\n\nIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.\n\nTheir blood is what I need to ink your parchment.  Bring it to me.Upon completion of this quest you will gain:", objectives = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes." }
WordHunterWoW_QuestEN[7564] = { title = "Wildeyes", description = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes." }
WordHunterWoW_QuestEN[7581] = { title = "The Prison's Bindings", description = "You must retrieve bindings for the prison of the Doomguard from lesser demons.\n\nThe blood of the Wildspawn satyr that occupy Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.Upon completion of this quest you will gain:", objectives = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done." }
WordHunterWoW_QuestEN[7582] = { title = "The Prison's Casing", description = "The Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as Tears of the Hederine.\n\nNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.\n\nTravel to Darkwhisper Gorge in Winterspring and recover the Tears.Upon completion of this quest you will gain:", objectives = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task." }
WordHunterWoW_QuestEN[7583] = { title = "Suppression", description = "The prison is ready. Now for the most difficult portion of this task.\n\nYou must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison.\n\nBe warned! A Doomguard is a cunning and lethal adversary and will seek to destroy you as you begin the ritual of imprisonment. It will flail wildly in its attempts to escape imprisonment.\n\nIt will focus on nothing but you, <name>. Because of this, I must recommend that you take companions capable of keeping you alive!You will learn:", objectives = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar." }
WordHunterWoW_QuestEN[7601] = { title = "What Niby Commands", description = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.\n\nMy imp, Impsy, shall set you on your way.", objectives = "Speak with Impsy in Felwood." }
WordHunterWoW_QuestEN[7602] = { title = "Flawless Fel Essence", description = "If you're going to reanimate Kroshius, you're going to need Fel fire. I can make Fel fire but it's going to require some components.\n\nYou need to bring me flawless Fel essences from three distinct regions of the world.\n\nThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.\n\nBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshius.Upon completion of this quest you will gain:", objectives = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\nRecover the Flawless Fel Essences and return to Impsy in Felwood." }
WordHunterWoW_QuestEN[7603] = { title = "Kroshius' Infernal Core", description = "Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal.\n\nAt this point, I fully expect him to kill you and your minion.\n\nIf by some miracle you happen to kill Kroshius, take his infernal core and return it to Niby.You will learn:", objectives = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood." }
WordHunterWoW_QuestEN[7604] = { title = "A Binding Contract", description = "The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to him as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.\n\nBy signing this contract, you are agreeing to all terms listed herein.\n\n_________________\n\nSignature", objectives = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron." }
WordHunterWoW_QuestEN[7621] = { title = "A Warning", description = "", objectives = "" }
WordHunterWoW_QuestEN[7622] = { title = "The Balance of Light and Shadow", description = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.\n\nThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.\n\nEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, <name>.", objectives = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\nYou may view the Death Post to view how many Peasants have been slain." }
WordHunterWoW_QuestEN[7623] = { title = "Lord Banehollow", description = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!\n\nThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.\n\nBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you...Upon completion of this quest you will gain:", objectives = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.\nUse the potions to travel through Jaedenar, and speak with Lord Banehollow." }
WordHunterWoW_QuestEN[7624] = { title = "Ulathek the Traitor", description = "You wish to enter my good graces?  Then kill for me.\n\nMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...\n\nProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar." }
WordHunterWoW_QuestEN[7625] = { title = "Xorothian Stardust", description = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?\n\nVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price.Upon completion of this quest you will gain:", objectives = "Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes." }
WordHunterWoW_QuestEN[7626] = { title = "Bell of Dethmoora", description = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.\n\nMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki.Upon completion of this quest you will gain:", objectives = "Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes." }
WordHunterWoW_QuestEN[7627] = { title = "Wheel of the Black March", description = "A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.\n\nAcquire these and bring them to my servant.Upon completion of this quest you will gain:", objectives = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes." }
WordHunterWoW_QuestEN[7628] = { title = "Doomsday Candle", description = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!\n\nContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes.Upon completion of this quest you will gain:", objectives = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes." }
WordHunterWoW_QuestEN[7629] = { title = "Imp Delivery", description = "There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!\n\nThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.\n\nI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment.Upon completion of this quest you will gain:", objectives = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes." }
WordHunterWoW_QuestEN[7630] = { title = "Arcanite", description = "Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.\n\nTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.\n\nReturn to me when you have the arcanite, and then I'll make the black lodestone.Upon completion of this quest you will gain:", objectives = "Bring 3 Arcanite Bar to Gorzeeki in the Burning Steppes." }
WordHunterWoW_QuestEN[7631] = { title = "Dreadsteed of Xoroth", description = "All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.\n\nI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.\n\nFortune to you, <name>.  And may the souls of your enemies swiftly find their way into your shard pouch.You will learn:", objectives = "Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you." }
WordHunterWoW_QuestEN[7632] = { title = "The Ancient Leaf", description = "The epidermis of the leaf glows a bright green. The surface is extremely rugose, exposing several veins and wrinkles.\n\nIf you had to take a guess, you would say this leaf came from something ancient and powerful.\n\nMaybe you should find the original owner of this leaf?", objectives = "Find the owner of the Ancient Petrified Leaf. Good luck, $N; It's a big world." }
WordHunterWoW_QuestEN[7633] = { title = "An Introduction", description = "", objectives = "" }
WordHunterWoW_QuestEN[7634] = { title = "Ancient Sinew Wrapped Lamina", description = "Greetings, <class>. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.\n\nWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.\n\nReturn here with sinew from an adult blue dragon and this quiver shall be yours.", objectives = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood." }
WordHunterWoW_QuestEN[7635] = { title = "A Proper String", description = "Vartrus may offer you the stave to create a bow of Ancients but only I can enchant the string required to complete the bow.\n\nIt is a simple task, puny one. Slay a mature black dragon and remove the sinew from its bones. Return that sinew to me and I shall enchant the material into an almost indestructible bow string.You will receive:", objectives = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood." }
WordHunterWoW_QuestEN[7636] = { title = "Stave of the Ancients", description = "Agents of the Burning Legion are still active in our world, <class>. These agents corrupt all that they touch. Nature wilts and weeps in their presence.\n\nYou must track down these demonic corrupters and destroy them, <name>. Be warned, you must engage them by yourself or they will flee. As long as you are alone, they will try and destroy you. You must strike at them, turning their arrogance into misery.\n\nI grant you a piece of my bark, the inscriptions shall lead you to your targets. Retrieve their heads.You will receive:", objectives = "You must find and destroy these four demonic corrupters:\nSimone the Seductress.\nKlinfran the Crazed.\nSolenor the Slayer.\nArtorius the Doombringer.\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\nYou MUST complete this task by yourself." }
WordHunterWoW_QuestEN[7637] = { title = "Emphasis on Sacrifice", description = "In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.\n\nYou must acquire High Priest Rohan's exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.\n\nProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.\n\nGo now <name>, time is of the essence.Upon completion of this quest you will gain:", objectives = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it." }
WordHunterWoW_QuestEN[7638] = { title = "Lord Grayson Shadowbreaker", description = "The time has come, <name>, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.\n\nSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.\n\nI wish you the best in this trial.  For the Light, noble <brother/sister>!", objectives = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District." }
WordHunterWoW_QuestEN[7639] = { title = "To Show Due Judgment", description = "With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.\n\nReturn now to Lord Grayson Shadowbreaker in Stormwind, <name>.  Your quest continues with him.Upon completion of this quest you will gain:", objectives = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
